async function loadTrainingWorkspace({ quiet = false } = {}) {
  const activeRunRow = document.activeElement?.closest?.("[data-training-run-id]");
  const restoreFocusedRunID = elements.trainingRunList.contains(document.activeElement)
    ? (activeRunRow?.dataset.trainingRunId || state.training.selectedRunID)
    : null;
  const generation = ++state.training.requestGeneration;
  state.training.loading = true;
  renderTrainingWorkspace();
  const query = new URLSearchParams({ mediaKind: state.training.mediaKind });
  if (state.training.method) query.set("method", state.training.method);
  try {
    const snapshot = await api(`/v1/training/workspace?${query}`);
    if (generation !== state.training.requestGeneration) return;
    const previousRunID = state.training.selectedRunID;
    state.training.runs = snapshot.runs || [];
    state.training.slots = snapshot.slots || [];
    state.training.activities = snapshot.activities || [];
    const focusedRun = state.training.runs.find(
      (run) => state.training.focusedRunID && run.id === state.training.focusedRunID
    ) || state.training.runs.find(
      (run) => state.training.focusedJobID && run.jobID === state.training.focusedJobID
    ) || state.training.runs.find(
      (run) => state.training.focusedTagID && run.tagID === state.training.focusedTagID
    );
    if (focusedRun && !visibleTrainingRuns().some((run) => run.id === focusedRun.id)) {
      state.training.runScope = "all";
    }
    const visibleRuns = visibleTrainingRuns();
    state.training.selectedRunID = focusedRun?.id
      || (visibleRuns.some((run) => run.id === previousRunID)
        ? previousRunID
        : (visibleRuns[0]?.id || null));
    if (state.training.selectedRunID !== previousRunID) resetTrainingDetailScroll();
    if (focusedRun) {
      state.training.focusedRunID = null;
      state.training.focusedJobID = null;
      state.training.focusedTagID = null;
    }
  } catch (error) {
    if (generation === state.training.requestGeneration && !quiet) {
      toast(error.message || "训练记录载入失败");
    }
  } finally {
    if (generation === state.training.requestGeneration) {
      state.training.loading = false;
      renderTrainingWorkspace();
      const pendingReturnFocusRunID = state.training.pendingReturnFocusRunID;
      state.training.pendingReturnFocusRunID = null;
      if (pendingReturnFocusRunID
        && !elements.trainingWorkspace.classList.contains("hidden")) {
        stabilizeDismissedOverlayFocus(
          () => elements.trainingRunList.querySelector(
            `[data-training-run-id="${CSS.escape(pendingReturnFocusRunID)}"]`
          ),
          elements.reviewWorkspace,
          () => !elements.trainingWorkspace.classList.contains("hidden")
        );
      } else if (restoreFocusedRunID) {
        const nextFocusID = visibleTrainingRuns().some((run) => run.id === restoreFocusedRunID)
          ? restoreFocusedRunID
          : state.training.selectedRunID;
        focusTrainingRun(nextFocusID);
      }
    }
  }
}

async function openTrainingWorkspace({
  returnToReview = null,
  historyMode = "push",
} = {}) {
  elements.reviewWorkspace.classList.add("hidden");
  if (returnToReview) {
    state.training.returnTarget = {
      workspace: "review",
      mode: returnToReview.mode || "overview",
      tagID: returnToReview.tagID || null,
      jobID: returnToReview.jobID || null,
    };
  } else {
    state.training.returnTarget = null;
    state.reviewReturnFocus = null;
  }
  elements.slimmingWorkspace.classList.add("hidden");
  state.slimmingReturnFocus = null;
  closeJobsPopover({ restoreFocus: false });
  elements.filterPopover.classList.add("hidden");
  elements.filterButton.setAttribute("aria-expanded", "false");
  if (elements.trainingWorkspace.classList.contains("hidden")) {
    state.trainingReturnFocus = document.activeElement;
  }
  elements.appView.inert = true;
  elements.trainingWorkspace.classList.remove("hidden");
  recordWorkspaceHistory(
    "training",
    returnToReview ? { returnToReview } : null,
    historyMode
  );
  syncTrainingClosePresentation();
  requestAnimationFrame(() => {
    elements.closeTrainingButton.focus({ preventScroll: true });
  });
  await loadTrainingWorkspace();
}

async function switchTrainingMediaKind(mediaKind) {
  if (!["image", "video"].includes(mediaKind)
    || mediaKind === state.training.mediaKind) return;
  state.training.mediaKind = mediaKind;
  state.training.selectedRunID = null;
  await loadTrainingWorkspace();
}

function slimmingModeText(mode) {
  return {
    catalog: "全部来源",
    currentFilter: "当前筛选",
    seeds: "从所选项目查找",
  }[mode] || "分析";
}

function slimmingJobStateText(job) {
  if (job?.state === "running" && job.controlRequest === "pause") return "正在暂停";
  if (job?.state === "running" && job.controlRequest === "cancel") return "正在取消";
  return jobStateText(job || {});
}

function slimmingScanPhaseText(progress) {
  if (!progress) return "";
  return {
    preparingFingerprints: "补全内容指纹",
    loadingFeaturePrints: "加载 Feature Print",
    loadingEmbeddings: "加载 DINOv2 向量",
    clustering: "聚类分析",
  }[progress.phase] || "分析中";
}

function selectedSlimmingJob() {
  return state.slimming.jobs.find((job) => job.id === state.slimming.selectedJobID) || null;
}

function selectedSlimmingJobIndex() {
  return state.slimming.jobs.findIndex((job) => job.id === state.slimming.selectedJobID);
}

function totalSlimmingJobCount() {
  return Math.max(state.slimming.jobs.length, Number(state.slimming.totalJobCount || 0));
}

function hasMoreSlimmingJobs() {
  return state.slimming.jobLimit < totalSlimmingJobCount()
    && state.slimming.jobLimit < SLIMMING_JOB_LIMIT_MAX;
}

async function expandSlimmingJobWindow({ all = false } = {}) {
  if (state.slimming.loading || !hasMoreSlimmingJobs()) return false;
  const previousLimit = state.slimming.jobLimit;
  const target = all
    ? totalSlimmingJobCount()
    : previousLimit + SLIMMING_JOB_PAGE_SIZE;
  state.slimming.jobLimit = Math.min(SLIMMING_JOB_LIMIT_MAX, target);
  const loaded = await loadSlimmingWorkspace({ quiet: true });
  if (!loaded) {
    state.slimming.jobLimit = previousLimit;
    renderSlimmingWorkspace();
    return false;
  }
  return state.slimming.jobLimit > previousLimit;
}

function focusSelectedSlimmingJob() {
  requestAnimationFrame(() => {
    const selected = elements.slimmingJobList.querySelector('[aria-selected="true"]');
    selected?.focus({ preventScroll: true });
    selected?.scrollIntoView({ block: "nearest", inline: "center" });
  });
}

function focusSelectedSlimmingCluster({ fallbackToScope = true } = {}) {
  requestAnimationFrame(() => {
    const selected = elements.slimmingClusterList.querySelector(
      '[data-slimming-cluster-id][aria-pressed="true"]'
    );
    if (selected) {
      selected.focus({ preventScroll: true });
      selected.scrollIntoView({ block: "nearest", inline: "nearest" });
      return;
    }
    if (fallbackToScope) {
      elements.slimmingClusterScopes.querySelector(
        `[data-slimming-cluster-scope="${CSS.escape(state.slimming.clusterScope)}"]`
      )?.focus({ preventScroll: true });
    }
  });
}

function slimmingClusterScopeText(scope) {
  return { pending: "待处理", confirmed: "已确认", ignored: "已忽略" }[scope] || "待处理";
}

async function navigateSlimmingJob(target) {
  if (!state.slimming.jobs.length || state.slimming.loading) return;
  let current = Math.max(0, selectedSlimmingJobIndex());
  if ((target === "last" || (Number(target) > 0 && current >= state.slimming.jobs.length - 1))
    && hasMoreSlimmingJobs()) {
    await expandSlimmingJobWindow({ all: target === "last" });
    current = Math.max(0, selectedSlimmingJobIndex());
  }
  const index = target === "first"
    ? 0
    : target === "last"
      ? state.slimming.jobs.length - 1
      : Math.max(0, Math.min(state.slimming.jobs.length - 1, current + Number(target)));
  const job = state.slimming.jobs[index];
  if (!job || job.id === state.slimming.selectedJobID) return;
  state.slimming.selectedJobID = job.id;
  state.slimming.selectedClusterID = null;
  state.slimming.selectedMemberIDs.clear();
  state.slimming.selectionAnchorID = null;
  state.slimming.clusterLimit = 48;
  state.slimming.memberLimit = 96;
  await loadSlimmingWorkspace({ jobID: job.id });
  focusSelectedSlimmingJob();
}

function appendSlimmingScanProgress(container, job, compact = false) {
  const scan = job?.scanProgress;
  if (!scan) return;
  const completed = Math.max(0, Number(scan.completedUnitCount || 0));
  const total = Math.max(1, Number(scan.totalUnitCount || 1));
  const wrapper = document.createElement("span");
  wrapper.className = `slimming-scan-progress${compact ? " compact" : ""}`;
  const track = document.createElement("span");
  track.className = "slimming-scan-progress-track";
  const fill = document.createElement("span");
  fill.style.width = `${Math.min(100, Math.max(0, completed / total * 100))}%`;
  track.append(fill);
  const copy = document.createElement("span");
  copy.textContent = `${slimmingScanPhaseText(scan)} ${completed}/${total}`;
  wrapper.append(track, copy);
  container.append(wrapper);
}

function slimmingClusterPresentation(cluster) {
  const currentMemberCount = Number(cluster.memberCount || 0);
  const originalMemberCount = Number(cluster.originalMemberCount || currentMemberCount);
  const historicalDetail = cluster.isHistoricalProcessedRecord
    ? `原 ${originalMemberCount} 项 · 现 ${currentMemberCount} 项可查看`
    : null;
  if (cluster.isSeedOnlyResult) {
    return {
      title: state.slimming.mediaKind === "video" ? "种子视频" : "种子照片",
      detail: "未找到相似项 · 可继续检查所选项目",
    };
  }
  const video = state.slimming.mediaKind === "video";
  const title = {
    byteIdentical: video ? "完全相同视频" : "完全相同",
    perceptualDuplicate: video ? "代表缩略图重复" : "视觉重复",
    nearDuplicateScene: video ? "相似视频" : "同场景相似",
  }[cluster.kind] || "相似项目";
  const detail = cluster.kind === "byteIdentical"
    ? (video ? "完整视频文件一致" : "内容完全一致")
    : `${cluster.kind === "nearDuplicateScene" ? "相似度" : "匹配度"} ${Math.round(cluster.score * 100)}%`;
  return { title, detail, historicalDetail };
}

function renderSlimmingJobActions() {
  clearElement(elements.slimmingJobActions);
  const job = state.slimming.jobs.find((item) => item.id === state.slimming.selectedJobID);
  if (!job) return;
  const mutating = state.slimming.jobMutatingIDs.has(job.id);
  for (const action of job.availableActions || []) {
    if (!['pause', 'resume'].includes(action)) continue;
    const button = document.createElement("button");
    button.type = "button";
    button.className = "button button-compact write-action slimming-job-action";
    button.dataset.slimmingJobActionId = job.id;
    button.dataset.action = action;
    button.disabled = mutating;
    button.textContent = action === "pause" ? "暂停" : "继续";
    elements.slimmingJobActions.append(button);
  }
  if (job.state !== "running") {
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "button button-compact button-danger write-action slimming-job-action";
    remove.dataset.slimmingJobActionId = job.id;
    remove.dataset.action = "deleteRecord";
    remove.disabled = mutating;
    remove.textContent = "删除记录";
    remove.title = "只删除分析记录和结果，不会删除任何原始媒体";
    elements.slimmingJobActions.append(remove);
  }
}

function renderSlimmingJobs() {
  clearElement(elements.slimmingJobList);
  const totalCount = totalSlimmingJobCount();
  const loadedCount = state.slimming.jobs.length;
  const hasMore = hasMoreSlimmingJobs();
  elements.slimmingJobCount.textContent = `${totalCount} 条`;
  elements.slimmingJobCount.title = hasMore
    ? `已载入 ${loadedCount} / ${totalCount} 条分析记录`
    : `已载入全部 ${totalCount} 条分析记录`;
  const selectedIndex = selectedSlimmingJobIndex();
  elements.slimmingJobPosition.textContent = state.slimming.jobs.length
    ? `${Math.max(0, selectedIndex) + 1} / ${totalCount}`
    : "0 / 0";
  elements.previousSlimmingJobButton.disabled = state.slimming.loading || selectedIndex <= 0;
  elements.nextSlimmingJobButton.disabled = state.slimming.loading
    || selectedIndex < 0
    || (selectedIndex >= state.slimming.jobs.length - 1 && !hasMore);
  elements.slimmingLoadMoreJobsButton.classList.toggle("hidden", !hasMore);
  elements.slimmingLoadMoreJobsButton.disabled = state.slimming.loading;
  elements.slimmingLoadMoreJobsButton.textContent = hasMore
    ? `载入更多记录（剩余 ${Math.max(0, totalCount - loadedCount)}）`
    : "已载入全部记录";
  elements.slimmingEmpty.classList.toggle(
    "hidden",
    state.slimming.loading || state.slimming.jobs.length > 0
  );
  const activeCount = state.slimming.jobs.filter(
    (job) => ["pending", "running", "paused", "retryableFailed"].includes(job.state)
  ).length;
  elements.slimmingNavigationCount.textContent = activeCount ? String(activeCount) : "";
  for (const job of state.slimming.jobs) {
    const row = document.createElement("button");
    row.type = "button";
    row.className = "slimming-job-row";
    row.dataset.slimmingJobId = job.id;
    row.classList.toggle("selected", job.id === state.slimming.selectedJobID);
    row.setAttribute("role", "option");
    row.setAttribute("aria-selected", String(job.id === state.slimming.selectedJobID));
    row.tabIndex = job.id === state.slimming.selectedJobID ? 0 : -1;
    const heading = document.createElement("span");
    heading.className = "slimming-row-heading";
    const title = document.createElement("strong");
    title.textContent = slimmingModeText(job.mode);
    const status = document.createElement("span");
    status.className = `slimming-state ${job.state}`;
    status.textContent = slimmingJobStateText(job);
    heading.append(title, status);
    const counts = document.createElement("span");
    counts.className = "slimming-row-detail";
    const unit = job.mediaKind === "video" ? "个视频" : "张照片";
    const countParts = [`${job.memberCount} ${unit}`];
    if (job.seedCount > 0) countParts.push(`种子 ${job.seedCount}`);
    if (job.hasResult) countParts.push(`${job.clusterCount} 个簇`);
    countParts.push(`尝试 ${job.attempts}/${job.maxAttempts}`);
    counts.textContent = countParts.join(" · ");
    const source = document.createElement("span");
    source.className = "slimming-row-detail";
    source.textContent = job.sourceNames?.length ? job.sourceNames.join(" · ") : "全部可用来源";
    const date = document.createElement("span");
    date.className = "slimming-row-date";
    date.textContent = formatDate(job.updatedAtMs);
    row.append(heading, counts);
    appendSlimmingScanProgress(row, job, true);
    row.append(source, date);
    elements.slimmingJobList.append(row);
  }
  renderSlimmingJobActions();
}

function renderSlimmingJobStatus() {
  clearElement(elements.slimmingJobStatus);
  const job = selectedSlimmingJob();
  const visible = job && [
    "pending", "running", "paused", "retryableFailed", "terminalFailed", "cancelled",
  ].includes(job.state);
  elements.slimmingJobStatus.classList.toggle("hidden", !visible);
  if (!visible) return;
  elements.slimmingJobStatus.className = `slimming-job-status ${job.state}`;
  const copy = document.createElement("div");
  copy.className = "slimming-job-status-copy";
  const heading = document.createElement("strong");
  heading.textContent = slimmingJobStateText(job);
  const detail = document.createElement("span");
  const source = job.sourceNames?.length ? job.sourceNames.join("、") : "任务来源不可用";
  detail.textContent = `${slimmingModeText(job.mode)} · ${source} · 尝试 ${job.attempts}/${job.maxAttempts}`;
  copy.append(heading, detail);
  elements.slimmingJobStatus.append(copy);
  appendSlimmingScanProgress(elements.slimmingJobStatus, job);
  const actions = document.createElement("span");
  actions.className = "slimming-job-status-actions";
  const activity = document.createElement("button");
  activity.type = "button";
  activity.className = "button button-compact";
  activity.dataset.openJobActivityId = job.id;
  activity.textContent = "在任务中查看";
  actions.append(activity);
  if (job.state === "retryableFailed" && job.availableActions?.includes("resume")) {
    const resume = document.createElement("button");
    resume.type = "button";
    resume.className = "button button-compact write-action";
    resume.dataset.slimmingJobActionId = job.id;
    resume.dataset.action = "resume";
    resume.textContent = "继续分析";
    actions.append(resume);
  }
  elements.slimmingJobStatus.append(actions);
  if (["pending", "running"].includes(job.state)) {
    const guard = document.createElement("span");
    guard.className = "slimming-job-guard";
    guard.textContent = "分析完成或暂停前，一键清理保持锁定";
    elements.slimmingJobStatus.append(guard);
  }
  if (["retryableFailed", "terminalFailed"].includes(job.state)) {
    const diagnosis = document.createElement("span");
    diagnosis.className = "slimming-job-diagnosis";
    diagnosis.textContent = jobFailureGuidance(job);
    if (job.lastErrorCode) {
      const code = document.createElement("code");
      code.textContent = job.lastErrorCode;
      diagnosis.append(" ", code);
    }
    elements.slimmingJobStatus.append(diagnosis);
  }
}

function appendSlimmingInspectorField(label, value, className = "") {
  const wrapper = document.createElement("div");
  wrapper.className = `slimming-inspector-field${className ? ` ${className}` : ""}`;
  const term = document.createElement("dt");
  term.textContent = label;
  const detail = document.createElement("dd");
  detail.textContent = value || "—";
  wrapper.append(term, detail);
  elements.slimmingInspectorContent.append(wrapper);
}

function renderSlimmingInspector() {
  clearElement(elements.slimmingInspectorContent);
  const job = selectedSlimmingJob();
  const cluster = state.slimming.clusters.find(
    (item) => item.id === state.slimming.selectedClusterID
  ) || null;
  const clusterCopy = cluster ? slimmingClusterPresentation(cluster) : null;
  const sourceNames = [...new Set(
    state.slimming.members.map((member) => member.sourceName).filter(Boolean)
  )];
  elements.slimmingInspectorSummary.textContent = clusterCopy?.title
    || (job ? `${slimmingModeText(job.mode)} · ${slimmingJobStateText(job)}` : "分析概览");

  appendSlimmingInspectorField("分析记录", `${totalSlimmingJobCount()} 条`);
  appendSlimmingInspectorField("当前任务", job ? slimmingModeText(job.mode) : "未选择");
  appendSlimmingInspectorField("状态", job ? slimmingJobStateText(job) : "—");
  appendSlimmingInspectorField(
    "尝试次数",
    job ? `${job.attempts}/${job.maxAttempts}` : "—"
  );
  appendSlimmingInspectorField(
    "任务来源",
    job?.sourceNames?.length ? job.sourceNames.join("、") : "任务来源不可用",
    "technical"
  );
  appendSlimmingInspectorField(
    "分析范围",
    job ? `${job.memberCount} ${job.mediaKind === "video" ? "个" : "张"}` : "—"
  );
  appendSlimmingInspectorField("已分析", `${state.slimming.analyzedAssetCount} 项`);
  appendSlimmingInspectorField("待分析", `${state.slimming.pendingAnalysisCount} 项`);
  appendSlimmingInspectorField("策略版本", state.slimming.policyVersion || "—");

  if (cluster) {
    appendSlimmingInspectorField("类型", clusterCopy.title);
    appendSlimmingInspectorField(
      "成员",
      clusterCopy.historicalDetail || `${cluster.memberCount} 项`
    );
    appendSlimmingInspectorField("已选", `${state.slimming.selectedMemberIDs.size} 项`);
    appendSlimmingInspectorField("来源", sourceNames.join("、") || "正在读取…");
    appendSlimmingInspectorField("结果", clusterCopy.detail, "technical");
    appendSlimmingInspectorField(
      "技术详情",
      cluster.technicalSummary || "技术摘要不可用",
      "technical"
    );
  }
}

function renderSlimmingClusterScopes() {
  const supported = state.slimming.clusterScopeSupported;
  for (const button of elements.slimmingClusterScopes.querySelectorAll(
    "[data-slimming-cluster-scope]"
  )) {
    const scope = button.dataset.slimmingClusterScope;
    const advancedUnavailable = supported === false && scope !== "pending";
    const count = supported === false && scope !== "pending"
      ? "—"
      : Number(state.slimming.clusterScopeCounts?.[scope] || 0).toLocaleString();
    button.setAttribute("aria-pressed", String(scope === state.slimming.clusterScope));
    button.disabled = state.slimming.loading || advancedUnavailable;
    button.title = advancedUnavailable
      ? "需要新版 Mac Host 才能读取此审阅队列"
      : `${slimmingClusterScopeText(scope)}，${count} 组`;
    button.querySelector("[data-slimming-cluster-scope-count]").textContent = count;
  }
}

function appendSlimmingClusterReviewButton(container, cluster, disposition, label, symbol) {
  const active = cluster.reviewDisposition === disposition;
  const pending = state.slimming.clusterReviewPendingIDs.has(cluster.id);
  const button = document.createElement("button");
  button.type = "button";
  button.className = "slimming-cluster-review-button write-action";
  button.dataset.slimmingClusterReview = disposition;
  button.dataset.slimmingClusterReviewId = cluster.id;
  button.setAttribute("aria-pressed", String(active));
  button.setAttribute("aria-label", active ? `当前为${label}` : `设为${label}`);
  button.title = active ? `当前为${label}` : `将分组移入${label}队列`;
  button.disabled = !state.online || pending || active;
  const icon = document.createElement("span");
  icon.setAttribute("aria-hidden", "true");
  icon.textContent = pending ? "…" : symbol;
  const copy = document.createElement("span");
  copy.textContent = label;
  button.append(icon, copy);
  container.append(button);
}

function renderSlimmingSelectedClusterReview(cluster) {
  const supported = state.slimming.clusterScopeSupported === true;
  const disposition = cluster?.reviewDisposition || null;
  const pending = cluster && state.slimming.clusterReviewPendingIDs.has(cluster.id);
  const visible = Boolean(supported && cluster && disposition);
  elements.slimmingSelectedClusterReview.classList.toggle("hidden", !visible);
  if (!visible) {
    elements.slimmingSelectedClusterReviewStatus.textContent = "";
    elements.slimmingSelectedClusterReviewStatus.removeAttribute("data-disposition");
    return;
  }
  elements.slimmingSelectedClusterReviewStatus.dataset.disposition = disposition;
  elements.slimmingSelectedClusterReviewStatus.textContent = disposition === "confirmed"
    ? "✓ 已确认"
    : "⊘ 已忽略";
  elements.slimmingReprocessClusterButton.disabled = !state.online || pending;
  elements.slimmingReprocessClusterButton.dataset.slimmingClusterReviewId = cluster.id;
  elements.slimmingReprocessClusterButton.textContent = pending ? "正在保存…" : "重新处理";
}

function renderSlimmingClusters() {
  renderSlimmingClusterScopes();
  clearElement(elements.slimmingClusterList);
  elements.slimmingClusterScopeTitle.textContent = slimmingClusterScopeText(
    state.slimming.clusterScope
  );
  const totalClusterCount = state.slimming.clusterScopeSupported === true
    ? Number(state.slimming.clusterScopeCounts?.[state.slimming.clusterScope] || 0)
    : state.slimming.clusters.length;
  elements.slimmingClusterCount.textContent = totalClusterCount > state.slimming.clusters.length
    ? `${state.slimming.clusters.length} / ${totalClusterCount} 组`
    : `${state.slimming.clusters.length} 组`;
  elements.slimmingLoadMoreClustersButton.classList.toggle(
    "hidden",
    state.slimming.loading || state.slimming.clusters.length >= totalClusterCount
  );
  elements.slimmingClusterEmpty.classList.toggle(
    "hidden",
    state.slimming.loading || !state.slimming.selectedJobID || state.slimming.clusters.length > 0
  );
  const emptyTitle = elements.slimmingClusterEmpty.querySelector("strong");
  const emptyMessage = elements.slimmingClusterEmpty.querySelector("p");
  if (state.slimming.selectedJobID && state.slimming.clusterScopeSupported === true) {
    emptyTitle.textContent = `${slimmingClusterScopeText(state.slimming.clusterScope)}队列为空`;
    emptyMessage.textContent = state.slimming.clusterScope === "pending"
      ? "此记录没有尚待处理的重复或相似分组。"
      : `此记录没有${slimmingClusterScopeText(state.slimming.clusterScope)}的分组。`;
  } else {
    emptyTitle.textContent = "没有候选分组";
    emptyMessage.textContent = "此记录未发现重复或相似项目。";
  }
  for (const cluster of state.slimming.clusters) {
    const copy = slimmingClusterPresentation(cluster);
    const row = document.createElement("div");
    row.className = "slimming-cluster-row";
    row.dataset.slimmingClusterRowId = cluster.id;
    row.classList.toggle("selected", cluster.id === state.slimming.selectedClusterID);
    row.setAttribute("role", "listitem");
    const main = document.createElement("button");
    main.type = "button";
    main.className = "slimming-cluster-main";
    main.dataset.slimmingClusterId = cluster.id;
    main.setAttribute("aria-pressed", String(cluster.id === state.slimming.selectedClusterID));
    main.setAttribute("aria-label", `${copy.title}，${cluster.memberCount} 项，${copy.detail}`);
    const image = cluster.isHistoricalProcessedRecord && Number(cluster.memberCount || 0) === 0
      ? document.createElement("span")
      : document.createElement("img");
    if (image instanceof HTMLImageElement) {
      image.loading = "lazy";
      image.alt = "";
      image.setAttribute("aria-hidden", "true");
      setProtectedImageSource(
        image,
        `/v1/assets/${cluster.representativeAssetID}/thumbnail?w=180&rev=0`
      );
    } else {
      image.className = "slimming-cluster-history-mark";
      image.setAttribute("aria-hidden", "true");
      image.textContent = "✓";
    }
    const text = document.createElement("span");
    text.className = "slimming-cluster-copy";
    const title = document.createElement("strong");
    title.textContent = cluster.isHistoricalProcessedRecord
      ? `${copy.title} · ${copy.historicalDetail}`
      : `${copy.title} · ${cluster.memberCount} 项`;
    const detail = document.createElement("span");
    detail.textContent = cluster.isHistoricalProcessedRecord
      ? `历史处理记录 · ${copy.detail}`
      : copy.detail;
    text.append(title, detail);
    main.append(image, text);
    row.append(main);
    if (state.slimming.clusterScopeSupported === true) {
      const actions = document.createElement("span");
      actions.className = "slimming-cluster-review-actions";
      appendSlimmingClusterReviewButton(actions, cluster, "confirmed", "已确认", "✓");
      appendSlimmingClusterReviewButton(actions, cluster, "ignored", "忽略", "⊘");
      row.append(actions);
    }
    elements.slimmingClusterList.append(row);
  }
}

function syncSlimmingSelectionModeControls() {
  const available = state.slimming.view === "analysis"
    && state.slimming.members.length > 0;
  if (!available) state.slimming.selectionMode = false;
  const active = available && state.slimming.selectionMode;
  const selectedCount = state.slimming.selectedMemberIDs.size;
  elements.slimmingWorkspace.classList.toggle("touch-selection-mode", active);
  elements.slimmingSelectionModeButton.classList.toggle("hidden", !available);
  elements.slimmingSelectionModeButton.disabled = state.slimming.loading;
  elements.slimmingSelectionModeButton.setAttribute("aria-pressed", String(active));
  elements.slimmingSelectionModeButton.textContent = active ? "完成" : "选择";
  elements.slimmingSelectionModeButton.title = active
    ? `结束触控多选${selectedCount ? `，当前已选择 ${selectedCount} 项` : ""}`
    : "进入触控多选模式";
  elements.slimmingSelectionModeButton.setAttribute(
    "aria-label",
    active
      ? `完成多选${selectedCount ? `，当前已选择 ${selectedCount} 项` : ""}`
      : "选择多个瘦身候选项目"
  );
  elements.slimmingSelectAllButton.classList.toggle("hidden", !active);
  elements.slimmingSelectAllButton.disabled = state.slimming.loading
    || selectedCount === state.slimming.members.length;
}

function setSlimmingSelectionMode(enabled, { restoreFocus = true } = {}) {
  const available = state.slimming.view === "analysis"
    && state.slimming.members.length > 0;
  const next = Boolean(enabled) && available;
  if (next === state.slimming.selectionMode) {
    syncSlimmingSelectionModeControls();
    return;
  }
  state.slimming.selectionMode = next;
  if (next && state.slimming.selectedMemberIDs.size === 0) {
    const memberID = state.slimming.selectionAnchorID || state.slimming.members[0]?.id;
    if (memberID) {
      state.slimming.selectedMemberIDs = new Set([memberID]);
      state.slimming.selectionAnchorID = memberID;
    }
  } else if (!next && state.slimming.members.length > 0) {
    const memberIDs = new Set(state.slimming.members.map((member) => member.id));
    let memberID = state.slimming.selectionAnchorID;
    if (!memberID || !state.slimming.selectedMemberIDs.has(memberID)) {
      memberID = [...state.slimming.selectedMemberIDs].find((id) => memberIDs.has(id)) || null;
    }
    if (!memberID) memberID = state.slimming.members[0]?.id || null;
    state.slimming.selectedMemberIDs = memberID ? new Set([memberID]) : new Set();
    state.slimming.selectionAnchorID = memberID;
  }
  renderSlimmingMemberSelection();
  if (restoreFocus) {
    elements.slimmingSelectionModeButton.focus({ preventScroll: true });
  }
}

function renderSlimmingMemberSelection({ renderInspector = true } = {}) {
  for (const card of elements.slimmingMemberGrid.querySelectorAll("[data-slimming-member-id]")) {
    const selected = state.slimming.selectedMemberIDs.has(card.dataset.slimmingMemberId);
    card.classList.toggle("selected", selected);
    slimmingMemberMainButton(card)?.setAttribute("aria-pressed", String(selected));
    syncSlimmingMemberFavoriteButton(
      card,
      state.slimming.members.find((member) => member.id === card.dataset.slimmingMemberId)
    );
  }
  const selectedCount = state.slimming.selectedMemberIDs.size;
  elements.slimmingSelectionSummary.textContent = selectedCount
    ? `已选择 ${selectedCount} 项`
    : "";
  elements.slimmingSelectionBar.classList.toggle("hidden", selectedCount === 0);
  elements.slimmingSelectionBarSummary.textContent = `已选择 ${selectedCount} 项`;
  syncSlimmingSelectionModeControls();
  const active = currentSlimmingRemovalRequest()?.phase;
  const identicalActive = currentSlimmingIdenticalCleanupRequest()?.phase;
  const unavailable = state.slimming.removal.submitting
    || active === "awaitingMac"
    || active === "running"
    || identicalActive === "awaitingMac"
    || identicalActive === "running";
  elements.slimmingMoveToRecycleButton.disabled = unavailable || selectedCount === 0;
  elements.slimmingReleaseSpaceButton.disabled = unavailable || selectedCount === 0;
  if (renderInspector) renderSlimmingInspector();
}

function slimmingMemberMainButton(card, { create = false } = {}) {
  let button = card?.querySelector(":scope > .slimming-member-main") || null;
  if (!button && create && card) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "slimming-member-main";
    card.append(button);
  }
  return button;
}

function activeSlimmingRemovalPhase(assetID) {
  const request = state.slimming.removal.requests.find((candidate) =>
    ["awaitingMac", "running"].includes(candidate.phase)
      && candidate.jobID === state.slimming.selectedJobID
      && candidate.clusterID === state.slimming.selectedClusterID
      && (candidate.assetIDs || []).includes(assetID)
  );
  return request?.phase || null;
}

function syncSlimmingMemberFavoriteButton(card, member) {
  let button = card?.querySelector(":scope > .slimming-member-favorite") || null;
  if (!card || !supportsFavorites() || !member?.favorite) {
    button?.remove();
    return;
  }
  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "slimming-member-favorite write-action";
    button.dataset.slimmingMemberFavorite = "true";
    const icon = document.createElement("span");
    icon.className = "slimming-member-favorite-icon media-favorite-icon";
    icon.setAttribute("aria-hidden", "true");
    const badge = document.createElement("span");
    badge.className = "slimming-member-favorite-sync media-favorite-sync hidden";
    badge.setAttribute("aria-hidden", "true");
    button.append(icon, badge);
    card.append(button);
  }
  syncMediaFavoriteButton(button, {
    assetID: member.id,
    fileName: member.fileName,
    favorite: member.favorite,
  });
  const removalPhase = activeSlimmingRemovalPhase(member.id);
  if (removalPhase) {
    button.disabled = true;
    const reason = removalPhase === "awaitingMac"
      ? "等待 Mac 确认回收时不能更改红心"
      : "正在处理回收时不能更改红心";
    button.title = reason;
    button.setAttribute("aria-label", `${member.fileName || "当前项目"}：${reason}`);
  }
}

function syncSlimmingRecycleFavoriteButton(card, entry) {
  let button = card?.querySelector(":scope > .slimming-recycle-favorite") || null;
  if (!card || !supportsFavorites() || !entry?.favorite) {
    button?.remove();
    return;
  }
  if (!button) {
    button = document.createElement("button");
    button.type = "button";
    button.className = "slimming-recycle-favorite write-action";
    button.dataset.slimmingRecycleFavorite = "true";
    const icon = document.createElement("span");
    icon.className = "slimming-recycle-favorite-icon media-favorite-icon";
    icon.setAttribute("aria-hidden", "true");
    const badge = document.createElement("span");
    badge.className = "slimming-recycle-favorite-sync media-favorite-sync hidden";
    badge.setAttribute("aria-hidden", "true");
    button.append(icon, badge);
    card.append(button);
  }
  syncMediaFavoriteButton(button, {
    assetID: entry.assetID,
    fileName: entry.fileName,
    favorite: entry.favorite,
  });
  const warning = entry.sourceKind === "photos"
    ? "红心只用于整理，不会暂停系统“照片”的永久删除"
    : "红心只用于整理，不会阻止恢复、回收或永久删除";
  button.title = `${button.title}；${warning}`;
  button.setAttribute("aria-label", `${entry.fileName || "当前项目"}：${button.title}`);
}

async function toggleSlimmingMemberFavorite(button) {
  const card = button?.closest(".slimming-member-card");
  const assetID = button?.dataset.mediaFavoriteAssetId || card?.dataset.slimmingMemberId;
  const memberIndex = state.slimming.members.findIndex((member) => member.id === assetID);
  const favorite = favoriteStateForAssetID(assetID);
  if (!assetID || memberIndex < 0 || !favorite || state.favoriteMutating
    || activeSlimmingRemovalPhase(assetID)) return;

  const scrollContainer = slimmingMemberScrollContainer();
  const scrollTop = scrollContainer.scrollTop;
  const selectedMemberIDs = new Set(state.slimming.selectedMemberIDs);
  const selectionAnchorID = state.slimming.selectionAnchorID;
  await applyFavoriteMutation([assetID], favorite.isFavorite !== true);
  state.slimming.selectedMemberIDs = selectedMemberIDs;
  state.slimming.selectionAnchorID = selectionAnchorID;
  renderSlimmingMemberSelection();
  scrollContainer.scrollTop = scrollTop;

  if (button.isConnected) {
    button.focus({ preventScroll: true });
    return;
  }
  const fallback = elements.slimmingMemberGrid.querySelector(
    `[data-slimming-member-id="${CSS.escape(state.slimming.members[memberIndex]?.id || "")}"]`
  );
  slimmingMemberMainButton(fallback)?.focus({ preventScroll: true });
}

async function toggleSlimmingRecycleFavorite(button) {
  const card = button?.closest(".slimming-recycle-thumbnail-card");
  const entry = state.slimming.recycle.entries.find(
    (candidate) => candidate.id === card?.dataset.slimmingRecycleThumbnailEntryId
  );
  const assetID = button?.dataset.mediaFavoriteAssetId || entry?.assetID;
  const favorite = favoriteStateForAssetID(assetID);
  if (!entry || !assetID || !favorite || state.favoriteMutating) return;
  const scrollTop = elements.slimmingRecycleBody.scrollTop;
  await applyFavoriteMutation([assetID], favorite.isFavorite !== true);
  elements.slimmingRecycleBody.scrollTop = scrollTop;
  if (button.isConnected) button.focus({ preventScroll: true });
}

function currentSlimmingRemovalRequest() {
  return state.slimming.removal.requests.find((request) =>
    request.phase === "awaitingMac" || request.phase === "running"
  ) || state.slimming.removal.requests.find((request) =>
    request.jobID === state.slimming.selectedJobID
      && request.clusterID === state.slimming.selectedClusterID
      && Date.now() - Number(request.updatedAtMs || 0) < 10 * 60 * 1000
  ) || null;
}

function currentSlimmingIdenticalCleanupRequest() {
  return state.slimming.identicalCleanup.requests.find(
    (request) => request.phase === "running"
  ) || state.slimming.identicalCleanup.requests.find(
    (request) => request.phase === "awaitingMac"
  ) || state.slimming.identicalCleanup.requests.find((request) =>
    request.jobID === state.slimming.selectedJobID
      && Date.now() - Number(request.updatedAtMs || 0) < 10 * 60 * 1000
  ) || null;
}

function runningIdenticalCleanupRequest() {
  return state.slimming.identicalCleanup.requests.find(
    (request) => request.phase === "running"
  ) || null;
}

function identicalCleanupExecutionPresentation(request) {
  const stage = request?.executionStage
    || (request?.progress?.totalAssetCount ? "recyclingAssets" : null);
  const presentations = {
    validatingPlan: {
      icon: "✓",
      title: "正在复核清理方案",
      detail: "重新读取照片与来源状态，确认清理范围没有变化。",
    },
    recyclingAssets: {
      icon: "⌫",
      title: request?.mode === "releaseSourceSpace"
        ? "正在清理完全相同媒体"
        : "正在移入回收站",
      detail: "按已确认的优先级逐项处理；这里显示本次运行的实际进度。",
    },
    requestingAuthorization: {
      icon: "⌑",
      title: "正在等待系统授权",
      detail: "如有系统窗口，请先完成照片或文件夹访问授权。",
    },
    refreshingState: {
      icon: "↻",
      title: "正在刷新删除状态",
      detail: "重新读取回收记录和当前可用状态。",
    },
    verifyingResult: {
      icon: "✓",
      title: "正在进行删除后核验",
      detail: "实打实统计已完成去重、仍有冗余和状态待确认的照片。",
    },
  };
  return {
    stage,
    ...(presentations[stage] || {
      icon: "…",
      title: "正在处理清理方案",
      detail: request?.message || "Mac 正在安全执行并核验本次清理。",
    }),
  };
}

function closeIdenticalCleanupBlockingOverlay({ restoreFocus = true } = {}) {
  const cleanup = state.slimming.identicalCleanup;
  const returnFocus = cleanup.blockingReturnFocus;
  cleanup.blockingReturnFocus = null;
  if (elements.identicalCleanupBlockingDialog.open) {
    elements.identicalCleanupBlockingDialog.close();
  }
  if (restoreFocus) {
    restoreOverlayFocus(stableReturnFocusTarget(returnFocus, elements.commandButton));
  }
}

function renderIdenticalCleanupBlockingOverlay() {
  const cleanup = state.slimming.identicalCleanup;
  const request = runningIdenticalCleanupRequest();
  if (!request) {
    if (elements.identicalCleanupBlockingDialog.open) {
      closeIdenticalCleanupBlockingOverlay();
    }
    return;
  }

  const presentation = identicalCleanupExecutionPresentation(request);
  elements.identicalCleanupBlockingIcon.textContent = presentation.icon;
  elements.identicalCleanupBlockingTitle.textContent = presentation.title;
  elements.identicalCleanupBlockingDetail.textContent = presentation.detail;
  const total = Math.max(0, Number(request.progress?.totalAssetCount || 0));
  const completed = Math.min(
    total,
    Math.max(0, Number(request.progress?.completedAssetCount || 0))
  );
  const determinate = presentation.stage === "recyclingAssets" && total > 0;
  elements.identicalCleanupBlockingIndeterminate.classList.toggle("hidden", determinate);
  elements.identicalCleanupBlockingProgress.classList.toggle("hidden", !determinate);
  if (determinate) {
    elements.identicalCleanupBlockingProgressBar.max = total;
    elements.identicalCleanupBlockingProgressBar.value = completed;
    elements.identicalCleanupBlockingProgressBar.setAttribute(
      "aria-label",
      `已处理 ${completed} / ${total} 张`
    );
    elements.identicalCleanupBlockingProgressLabel.textContent =
      `已处理 ${completed.toLocaleString("zh-CN")} / ${total.toLocaleString("zh-CN")} 张`;
  }
  elements.identicalCleanupBlockingDialog.setAttribute(
    "aria-label",
    determinate
      ? `${presentation.title}，已处理 ${completed} / ${total} 张，其他操作已锁定`
      : `${presentation.title}，其他操作已锁定`
  );

  if (!elements.identicalCleanupBlockingDialog.open) {
    cleanup.blockingReturnFocus = document.activeElement instanceof HTMLElement
      ? document.activeElement
      : null;
    hidePersistentHelp();
    hideContextMenus();
    closeCompactToolbarMenu({ restoreFocus: false });
    elements.identicalCleanupBlockingDialog.showModal();
    requestAnimationFrame(() => {
      elements.identicalCleanupBlockingCard.focus({ preventScroll: true });
    });
  }
}

function renderSlimmingRemovalStatus() {
  const request = currentSlimmingIdenticalCleanupRequest()
    || currentSlimmingRemovalRequest();
  elements.slimmingRemovalStatus.classList.toggle("hidden", !request);
  clearElement(elements.slimmingRemovalStatus);
  if (!request) return;

  const header = document.createElement("div");
  header.className = "slimming-removal-status-header";
  const message = document.createElement("strong");
  message.textContent = request.message || "Mac 正在处理批量操作…";
  const phase = document.createElement("span");
  phase.className = "secondary";
  phase.textContent = {
    awaitingMac: "等待 Mac 确认",
    running: "处理中",
    completed: "已完成",
    cancelled: "已取消",
    failed: "未完成",
  }[request.phase] || request.phase;
  header.append(message, phase);
  elements.slimmingRemovalStatus.append(header);

  if (request.progress && request.phase === "running") {
    const progress = document.createElement("progress");
    progress.max = Math.max(1, Number(request.progress.totalAssetCount || 1));
    progress.value = Math.max(0, Number(request.progress.completedAssetCount || 0));
    progress.setAttribute(
      "aria-label",
      `已完成 ${progress.value}/${progress.max} 项`
    );
    elements.slimmingRemovalStatus.append(progress);
  }
  if (request.audit) {
    const audit = document.createElement("div");
    audit.className = "slimming-removal-audit";
    const parts = [];
    if (request.audit.hiddenAssetIDs?.length) {
      parts.push(`已从候选结果隐藏 ${request.audit.hiddenAssetIDs.length} 项`);
    }
    if (request.audit.failedAssetIDs?.length) {
      parts.push(`失败 ${request.audit.failedAssetIDs.length} 项`);
    }
    if (request.audit.authorizationRequiredAssetIDs?.length) {
      parts.push(`待来源授权 ${request.audit.authorizationRequiredAssetIDs.length} 项`);
    }
    if (request.audit.authorizationDeniedPhotosAssetIDs?.length) {
      parts.push(`Photos 未授权 ${request.audit.authorizationDeniedPhotosAssetIDs.length} 项`);
    }
    audit.textContent = parts.join(" · ") || "逐项结果已由 Mac 安全核验";
    elements.slimmingRemovalStatus.append(audit);
  }
  if (request.verification) {
    const verification = document.createElement("div");
    verification.className = "slimming-removal-audit";
    verification.textContent = request.verification.isComplete
      ? `已独立核验：${request.verification.verifiedGroupCount}/${request.verification.targetGroupCount} 组均只保留一项`
      : `核验结果：完成 ${request.verification.verifiedGroupCount}/${request.verification.targetGroupCount} 组 · 尚有 ${request.verification.remainingRedundantAssetCount} 项冗余`;
    elements.slimmingRemovalStatus.append(verification);
    const report = document.createElement("button");
    report.type = "button";
    report.className = "button button-compact slimming-verification-button";
    report.dataset.slimmingVerificationRequestId = request.id;
    report.textContent = "查看完整核验报告";
    elements.slimmingRemovalStatus.append(report);
  }
}

function appendSlimmingVerificationMetric(label, value, tone) {
  const card = document.createElement("div");
  card.className = `identical-cleanup-metric ${tone || ""}`;
  const title = document.createElement("span");
  title.textContent = label;
  const count = document.createElement("strong");
  count.textContent = Number(value || 0).toLocaleString();
  card.append(title, count);
  elements.slimmingVerificationMetrics.append(card);
}

function openSlimmingVerificationReport(request) {
  const verification = request?.verification;
  if (!verification) return;
  const complete = Boolean(verification.isComplete);
  elements.slimmingVerificationDialog.classList.toggle("incomplete", !complete);
  elements.slimmingVerificationIcon.textContent = complete ? "✓" : "!";
  elements.slimmingVerificationTitle.textContent = complete
    ? "删除后核验完成"
    : "删除后核验存在未完成项";
  elements.slimmingVerificationSubtitle.textContent =
    "已重新读取本次处理资产的实时可用与回收状态。";
  elements.slimmingVerificationScore.textContent =
    `${verification.verifiedGroupCount} / ${verification.targetGroupCount}`;
  elements.slimmingVerificationGoal.textContent =
    `目标是每组保留 1 项，共 ${verification.targetRetainedAssetCount} 项；只把删除后确实仅剩 1 项的分组计入已完成。`;
  clearElement(elements.slimmingVerificationMetrics);
  appendSlimmingVerificationMetric("目标保留", verification.targetRetainedAssetCount, "blue");
  appendSlimmingVerificationMetric("当前实际可用", verification.currentAvailableAssetCount, "green");
  appendSlimmingVerificationMetric("完成去重", verification.verifiedGroupCount, "indigo");
  appendSlimmingVerificationMetric("尚未完成", verification.unresolvedGroupCount, complete ? "neutral" : "orange");
  clearElement(elements.slimmingVerificationResult);
  const heading = document.createElement("strong");
  heading.textContent = complete ? "核验完成" : "核验发现未完成项";
  const detail = document.createElement("p");
  detail.textContent = complete
    ? `实际读取 ${verification.observedAssetCount} 项，确认已清理 ${verification.recycledRedundantAssetCount} 项；处理范围内没有仍处于可用状态的计划删除项。`
    : `实际读取 ${verification.observedAssetCount} 项；确认已清理 ${verification.recycledRedundantAssetCount} 项；当前实际可用 ${verification.currentAvailableAssetCount} 项；仍可用冗余 ${verification.remainingRedundantAssetCount} 项；状态无法确认 ${verification.unresolvedAssetCount} 项。`;
  elements.slimmingVerificationResult.append(heading, detail);
  if (!elements.slimmingVerificationDialog.open) {
    elements.slimmingVerificationDialog.showModal();
  }
  requestAnimationFrame(() => elements.closeSlimmingVerificationButton.focus());
}

function closeSlimmingVerificationReport() {
  if (elements.slimmingVerificationDialog.open) {
    elements.slimmingVerificationDialog.close();
  }
}

function renderSlimmingMembers() {
  clearElement(elements.slimmingMemberGrid);
  const cluster = state.slimming.clusters.find(
    (item) => item.id === state.slimming.selectedClusterID
  );
  renderSlimmingSelectedClusterReview(cluster);
  const copy = cluster ? slimmingClusterPresentation(cluster) : null;
  const historicalEmpty = Boolean(
    cluster?.isHistoricalProcessedRecord && state.slimming.members.length === 0
  );
  elements.slimmingMemberEmpty.classList.toggle("hidden", Boolean(cluster) && !historicalEmpty);
  elements.slimmingMemberGrid.classList.toggle("hidden", !cluster || historicalEmpty);
  const emptyIcon = elements.slimmingMemberEmpty.querySelector("[aria-hidden='true']");
  const emptyTitle = elements.slimmingMemberEmpty.querySelector("strong");
  const emptyMessage = elements.slimmingMemberEmpty.querySelector("p");
  if (historicalEmpty) {
    emptyIcon.textContent = "✓";
    emptyTitle.textContent = "历史处理记录";
    emptyMessage.textContent = "原分组仍有审阅记录，但成员当前均已回收、清理或不再可查看。";
  } else {
    emptyIcon.textContent = "▧";
    emptyTitle.textContent = "选择一个候选分组";
    emptyMessage.textContent = "可使用普通点击、⌘ 点击、Shift 点击、⌘A 和拖拽空白框选成员；双击或按空格预览。";
  }
  elements.slimmingMemberTitle.textContent = copy?.title || "选择一个候选分组";
  const sourceNames = [...new Set(state.slimming.members.map((item) => item.sourceName).filter(Boolean))];
  elements.slimmingMemberSummary.textContent = cluster
    ? `${copy.detail} · ${copy.historicalDetail || `${state.slimming.members.length}/${cluster.memberCount} 项`} · ${sourceNames.join(" · ") || (historicalEmpty ? "成员当前不可查看" : "来源信息不可用")}`
    : "分组中的照片会在这里显示";
  elements.slimmingLoadMoreMembersButton.classList.toggle(
    "hidden",
    !cluster || state.slimming.loading || state.slimming.members.length >= cluster.memberCount
  );
  for (const member of state.slimming.members) {
    const card = document.createElement("div");
    card.className = "slimming-member-card";
    card.dataset.slimmingMemberId = member.id;
    if (Number(member.width) > 0 && Number(member.height) > 0) {
      card.style.setProperty(
        "--slimming-member-aspect",
        `${Number(member.width)} / ${Number(member.height)}`
      );
    }
    const main = slimmingMemberMainButton(card, { create: true });
    main.dataset.slimmingMemberMain = "true";
    main.setAttribute(
      "aria-label",
      `${member.fileName || "未命名项目"}，${member.sourceName || "来源未知"}`
    );
    main.setAttribute(
      "aria-keyshortcuts",
      "ArrowLeft ArrowRight ArrowUp ArrowDown Home End PageUp PageDown Space"
    );
    main.title = "方向键移动，Shift 扩展选择，Space 打开单图";
    const image = document.createElement("img");
    image.loading = "lazy";
    image.alt = "";
    image.setAttribute("aria-hidden", "true");
    syncProtectedThumbnailSource(image, member.id, {
      width: 360,
      revision: member.contentRevision || 0,
    });
    const footer = document.createElement("span");
    footer.className = "slimming-member-footer";
    const name = document.createElement("strong");
    name.textContent = member.fileName || "未命名项目";
    const source = document.createElement("span");
    source.textContent = member.sourceName || availabilityText(member.availability);
    footer.append(name, source);
    main.append(image, footer);
    if (state.slimming.mediaKind === "video") {
      const video = document.createElement("span");
      video.className = "slimming-member-video-badge";
      video.setAttribute("aria-hidden", "true");
      video.textContent = `▶${member.durationMs == null ? "" : ` ${formatDuration(member.durationMs)}`}`;
      main.append(video);
    }
    syncSlimmingMemberFavoriteButton(card, member);
    const removalPhase = activeSlimmingRemovalPhase(member.id);
    card.classList.toggle("pending-removal", Boolean(removalPhase));
    if (removalPhase) {
      main.disabled = true;
      const overlay = document.createElement("span");
      overlay.className = "slimming-member-pending-overlay";
      overlay.setAttribute("role", "status");
      overlay.setAttribute("aria-label", removalPhase === "awaitingMac"
        ? "等待 Mac 确认安全回收"
        : "正在安全处理回收");
      const spinner = document.createElement("span");
      spinner.className = "spinner";
      spinner.setAttribute("aria-hidden", "true");
      const copy = document.createElement("strong");
      copy.textContent = removalPhase === "awaitingMac" ? "等待 Mac 确认" : "正在移动";
      overlay.append(spinner, copy);
      card.append(overlay);
    }
    elements.slimmingMemberGrid.append(card);
  }
  renderSlimmingMemberSelection();
}

function slimmingRecycleCountdown(entry) {
  if (entry.sourceKind === "photos") {
    return "实际保留期限与永久删除由系统“照片”App 管理";
  }
  const remaining = Number(entry.purgeAfterMs) - Date.now();
  if (remaining <= 0) return "即将永久删除";
  const hour = 60 * 60 * 1000;
  const day = 24 * hour;
  if (remaining < day) return `${Math.max(1, Math.ceil(remaining / hour))} 小时后永久删除`;
  return `${Math.max(1, Math.ceil(remaining / day))} 天后永久删除`;
}

function slimmingRecycleStateCopy(entry) {
  if (entry.stateMessage) return entry.stateMessage;
  if (entry.resolution === "discardPreflightFailure") {
    return "未执行：缺少来源写入授权，可安全撤销失败意图";
  }
  if (entry.resolution === "retryInterruptedOperation") {
    return "操作曾被中断，需要重新检查原位置与隔离区";
  }
  if (entry.resolution === "inspect") {
    return `状态无法自动确定${entry.errorCode ? ` · ${entry.errorCode}` : ""}`;
  }
  return slimmingRecycleCountdown(entry);
}

function slimmingRecyclePolicyCopy(entry) {
  if (entry.policyMessage) return entry.policyMessage;
  if (entry.state === "recycled") return slimmingRecycleCountdown(entry);
  return "现有内容会继续受到保护";
}

function slimmingRecycleRecoveryDescriptor(entry) {
  switch (entry.resolution) {
    case "discardPreflightFailure":
    case "updateFolderAuthorization":
      return {
        kind: "source",
        action: "refreshFolderMutationAuthorization",
        label: "更新回收权限",
        help: "重新选择原文件夹，更新这个来源的回收与恢复权限；不会立即修改媒体。",
      };
    case "refreshSourceBeforeRetry":
      return {
        kind: "source",
        action: entry.sourceKind === "photos" ? "syncPhotos" : "rescan",
        label: "刷新来源",
        help: "重新读取这个来源的目录状态；完成后需重新分析，再重试清理。",
      };
    case "requestPhotosAuthorization":
      return {
        kind: "source",
        action: "requestPhotosWriteAuthorization",
        label: "请求照片权限",
        help: "请求 Apple Photos 完整读写授权；不会立即删除媒体。",
      };
    case "retryFromAnalysis":
      return {
        kind: "navigation",
        action: "analysis",
        label: "返回分析结果",
        help: "返回当前分析结果；核对媒体状态后可重新发起清理。",
      };
    default:
      return null;
  }
}

function slimmingRecycleShowsExplanation(entry) {
  return [
    "reinspectFileLocations",
    "updateFolderAuthorization",
    "refreshSourceBeforeRetry",
    "requestPhotosAuthorization",
    "retryFromAnalysis",
    "inspect",
  ].includes(entry.resolution);
}

function slimmingRecycleDirectActionLabel(entry, action) {
  if (action === "restore") return "恢复";
  if (action === "discardPreflightFailure") return "移除记录";
  if (action === "retryInterruptedOperation") {
    if (entry.resolution === "reinspectFileLocations") return "重新检查";
    return entry.state === "purging" ? "继续清理" : "继续协调";
  }
  if (action === "purge") return "立即删除";
  return action;
}

function slimmingRecycleDirectActionHelp(entry, action) {
  if (action === "restore") return "把这个文件夹媒体从 ImageAll 回收站恢复到原位置。";
  if (action === "discardPreflightFailure") {
    return "只移除这条未开始文件操作的失败记录；不会读写、移动或删除原文件。";
  }
  if (action === "retryInterruptedOperation") {
    return entry.resolution === "reinspectFileLocations"
      ? "只检查原位置与隔离区；只有结果唯一时才更新记录。"
      : "根据已登记的事务继续安全恢复；不会重复提交已经完成的来源删除。";
  }
  if (action === "purge") return "打开永久删除确认；确认后这个原始媒体将不可恢复。";
  return "";
}

function openSlimmingRecycleExplanation(entryID) {
  const entry = state.slimming.recycle.entries.find((item) => item.id === entryID);
  if (!entry || elements.slimmingRecycleExplanationDialog.open) return;
  state.slimming.recycle.explanationEntryID = entryID;
  state.slimming.recycle.explanationReturnFocus = document.activeElement;
  elements.slimmingRecycleExplanationTitle.textContent = entry.sourceKind === "photos"
    && entry.state === "recycled"
    ? "在“照片”App 中恢复"
    : entry.fileName || "回收处理说明";
  elements.slimmingRecycleExplanationSource.textContent = `${entry.sourceDisplayName} · ${
    entry.sourceKind === "photos" ? "Apple Photos" : "文件夹"
  }`;
  elements.slimmingRecycleExplanationState.textContent = slimmingRecycleStateCopy(entry);
  elements.slimmingRecycleExplanationPolicy.textContent = slimmingRecyclePolicyCopy(entry);
  elements.slimmingRecycleExplanationMessage.textContent = entry.explanationMessage
    || (entry.resolution === "photosManagedBySystem"
      ? "请在系统“照片”App 的“最近删除”中恢复；恢复后 ImageAll 会自动对账。永久删除也由系统管理。"
      : "本次操作没有形成可证明的完成状态。ImageAll 不会继续删除；请修正当前原因后再重试。");
  elements.slimmingRecycleExplanationDialog.showModal();
  restoreOverlayFocus(elements.closeSlimmingRecycleExplanationButton);
}

function closeSlimmingRecycleExplanation() {
  if (elements.slimmingRecycleExplanationDialog.open) {
    elements.slimmingRecycleExplanationDialog.close();
  }
}

function restoreSlimmingRecycleExplanationFocus() {
  const entryID = state.slimming.recycle.explanationEntryID;
  const fallback = state.slimming.recycle.explanationReturnFocus;
  state.slimming.recycle.explanationEntryID = null;
  state.slimming.recycle.explanationReturnFocus = null;
  const target = entryID
    ? elements.slimmingRecycleList.querySelector(
      `[data-slimming-recycle-explanation-id="${CSS.escape(entryID)}"]`
    )
    : null;
  restoreOverlayFocus(target || (fallback?.isConnected ? fallback : elements.slimmingButton));
}

function renderSlimmingRecycleSourceOptions() {
  const previous = state.slimming.recycle.sourceID;
  clearElement(elements.slimmingRecycleSourceSelect);
  const all = document.createElement("option");
  all.value = "";
  all.textContent = "全部来源";
  elements.slimmingRecycleSourceSelect.append(all);
  for (const source of state.sources) {
    const option = document.createElement("option");
    option.value = source.id;
    option.textContent = source.displayName;
    elements.slimmingRecycleSourceSelect.append(option);
  }
  elements.slimmingRecycleSourceSelect.value = previous;
  if (elements.slimmingRecycleSourceSelect.value !== previous) {
    state.slimming.recycle.sourceID = "";
  }
}

function renderSlimmingRecycleScopes() {
  const recycle = state.slimming.recycle;
  const labels = {
    all: "全部",
    photos: "Photos",
    files: "文件夹",
    attention: "待处理",
  };
  for (const button of elements.slimmingRecycleScopes.querySelectorAll(
    "[data-slimming-recycle-scope]"
  )) {
    const scope = button.dataset.slimmingRecycleScope;
    const count = recycle.scopeSupported === false && scope !== "all"
      ? "—"
      : Number(recycle.scopeCounts?.[scope] || 0).toLocaleString();
    button.setAttribute("aria-pressed", String(scope === recycle.scope));
    button.disabled = recycle.scopeSupported === false && scope !== "all";
    button.title = button.disabled
      ? "需要新版 Mac Host 才能按状态范围筛选"
      : `只显示${labels[scope]}范围内的回收站项目`;
    button.setAttribute("aria-label", `${labels[scope]}，${count} 项`);
    const countLabel = button.querySelector("[data-slimming-recycle-scope-count]");
    if (countLabel) countLabel.textContent = count;
  }
}

function renderSlimmingRecycleHeader() {
  const recycle = state.slimming.recycle;
  const allCount = recycle.scopeSupported === false
    ? Number(recycle.totalCount || 0)
    : Number(recycle.scopeCounts?.all || 0);
  const attentionCount = recycle.scopeSupported === true
    ? Number(recycle.scopeCounts?.attention || 0)
    : 0;
  const unit = state.slimming.mediaKind === "video" ? "个视频项目" : "张照片项目";
  elements.slimmingRecycleSummary.textContent = attentionCount > 0
    ? `当前 ${allCount.toLocaleString("zh-CN")} ${unit}，其中 ${attentionCount.toLocaleString("zh-CN")} 项需要关注`
    : `当前 ${allCount.toLocaleString("zh-CN")} ${unit}，均处于可恢复或系统管理状态`;

  const activeRequest = recycle.requests.some(
    (request) => ["awaitingMac", "running"].includes(request.phase)
  );
  elements.slimmingRecycleMutationStatus.classList.toggle(
    "hidden",
    recycle.mutatingEntryIDs.size === 0 && !activeRequest
  );

  const selectedSource = state.sources.find((source) => source.id === recycle.sourceID) || null;
  elements.slimmingRecycleSourceBanner.classList.toggle("hidden", !selectedSource);
  elements.slimmingRecycleSourceBannerName.textContent = selectedSource?.displayName || "";

  const hasSearch = Boolean(recycle.searchText.trim());
  elements.slimmingRecycleSearchResultCount.classList.toggle("hidden", !hasSearch);
  elements.clearSlimmingRecycleSearchButton.classList.toggle("hidden", !hasSearch);
  elements.slimmingRecycleSearchResultCount.textContent = hasSearch
    ? Number(recycle.totalCount || 0).toLocaleString("zh-CN")
    : "";
}

function renderSlimmingRecycleRequest() {
  const requests = state.slimming.recycle.requests || [];
  const active = requests.find((request) => ["awaitingMac", "running"].includes(request.phase));
  const latest = active || requests[0] || null;
  elements.slimmingRecycleRequestStatus.classList.toggle("hidden", !latest);
  elements.slimmingRecycleRequestStatus.textContent = latest
    ? `${latest.fileName || "回收站项目"}：${latest.message}`
    : "";
  if (!active && latest && ["completed", "cancelled", "failed"].includes(latest.phase)
    && state.slimming.recycle.lastTerminalRequestID !== latest.id) {
    state.slimming.recycle.lastTerminalRequestID = latest.id;
    toast(latest.message);
  }
}

function renderSlimmingRecycle() {
  const recycle = state.slimming.recycle;
  elements.slimmingRecycleSearchInput.value = recycle.searchText;
  renderSlimmingRecycleSourceOptions();
  renderSlimmingRecycleScopes();
  renderSlimmingRecycleHeader();
  elements.slimmingRecycleCount.textContent = recycle.totalCount > recycle.entries.length
    ? `${recycle.entries.length} / ${recycle.totalCount} 项`
    : `${recycle.totalCount} 项`;
  elements.slimmingRecycleLoadMoreButton.classList.toggle(
    "hidden",
    recycle.loading || recycle.entries.length >= recycle.totalCount
  );
  elements.slimmingRecycleEmpty.classList.toggle(
    "hidden",
    recycle.loading || recycle.entries.length > 0
  );
  const hasSearch = Boolean(recycle.searchText.trim());
  const hasSource = Boolean(recycle.sourceID);
  const allEmpty = Number(recycle.scopeCounts?.all || 0) === 0;
  let emptyPresentation;
  if (hasSearch) {
    emptyPresentation = {
      title: "没有匹配的媒体",
      message: `没有文件名包含“${recycle.searchText.trim()}”的回收站条目。`,
      action: "clearSearch",
      actionLabel: "清除搜索",
    };
  } else if (hasSource && allEmpty) {
    const sourceName = state.sources.find((source) => source.id === recycle.sourceID)
      ?.displayName || "当前来源";
    emptyPresentation = {
      title: "没有匹配的媒体",
      message: `“${sourceName}”当前没有回收或待处理项目。`,
      action: "clearSource",
      actionLabel: "显示全部来源",
    };
  } else if (recycle.scope !== "all" && recycle.entries.length === 0) {
    emptyPresentation = {
      title: "这个范围内没有媒体",
      message: "其他来源或处理状态中仍有回收站项目。",
      action: "showAll",
      actionLabel: "查看全部",
    };
  } else if (allEmpty) {
    emptyPresentation = {
      title: "回收站为空",
      message: "文件夹媒体在 ImageAll 中保留 30 天；Photos 项遵循系统“照片”App 的恢复规则。",
      action: null,
      actionLabel: "",
    };
  } else {
    emptyPresentation = {
      title: "没有匹配的媒体",
      message: "调整来源或清除文件名搜索以查看其他回收站项目。",
      action: "showAll",
      actionLabel: "查看全部",
    };
  }
  elements.slimmingRecycleEmptyTitle.textContent = emptyPresentation.title;
  elements.slimmingRecycleEmptyMessage.textContent = emptyPresentation.message;
  elements.slimmingRecycleEmptyAction.dataset.action = emptyPresentation.action || "";
  elements.slimmingRecycleEmptyAction.textContent = emptyPresentation.actionLabel;
  elements.slimmingRecycleEmptyAction.classList.toggle("hidden", !emptyPresentation.action);
  clearElement(elements.slimmingRecycleList);
  elements.slimmingRecycleList.classList.toggle("hidden", recycle.entries.length === 0);
  for (const entry of recycle.entries) {
    const row = document.createElement("article");
    row.className = "slimming-recycle-row";
    row.dataset.slimmingRecycleRowId = entry.id;
    const thumbnail = document.createElement("div");
    thumbnail.className = "slimming-recycle-thumbnail-card";
    thumbnail.dataset.slimmingRecycleThumbnailEntryId = entry.id;
    const image = document.createElement("img");
    image.className = "slimming-recycle-thumbnail";
    image.alt = "";
    image.setAttribute("aria-hidden", "true");
    syncProtectedThumbnailSource(image, entry.assetID, { width: 180 });
    thumbnail.append(image);
    if (entry.mediaKind === "video") {
      const video = document.createElement("span");
      video.className = "slimming-recycle-video-badge";
      video.textContent = "▶";
      video.setAttribute("aria-label", "视频代表缩略图");
      thumbnail.append(video);
    }
    syncSlimmingRecycleFavoriteButton(thumbnail, entry);
    const copy = document.createElement("div");
    copy.className = "slimming-recycle-copy";
    const title = document.createElement("strong");
    title.textContent = entry.fileName || "未命名媒体";
    const meta = document.createElement("span");
    meta.className = "slimming-recycle-meta";
    meta.textContent = `${entry.sourceKind === "photos" ? "Apple Photos" : "文件夹"} · ${entry.sourceDisplayName} · ${formatDate(entry.trashedAtMs)}`;
    const detail = document.createElement("span");
    detail.className = "slimming-recycle-detail";
    detail.classList.toggle("warning", entry.resolution !== "restoreOrPurge"
      && entry.resolution !== "photosManagedBySystem");
    detail.textContent = slimmingRecycleStateCopy(entry);
    const policy = document.createElement("span");
    policy.className = "slimming-recycle-policy";
    policy.textContent = slimmingRecyclePolicyCopy(entry);
    copy.append(title, meta, detail);
    const actions = document.createElement("div");
    actions.className = "slimming-recycle-actions";
    if (entry.resolution === "photosManagedBySystem") {
      const info = document.createElement("button");
      info.type = "button";
      info.className = "button button-compact";
      info.dataset.slimmingRecycleExplanationId = entry.id;
      info.dataset.helpDetail = "查看如何从 Apple Photos“最近删除”中恢复这个媒体。";
      info.textContent = "恢复说明";
      actions.append(info);
    }
    const recovery = slimmingRecycleRecoveryDescriptor(entry);
    if (recovery) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = `button button-compact${
        recovery.kind === "source" ? " write-action" : ""
      }`;
      button.dataset.slimmingRecycleEntryId = entry.id;
      button.dataset.slimmingRecycleRecoveryKind = recovery.kind;
      button.dataset.slimmingRecycleRecoveryAction = recovery.action;
      button.dataset.helpDetail = recovery.help;
      button.disabled = recycle.mutatingEntryIDs.has(entry.id)
        || (recovery.kind === "source"
          && (state.sourceManagement.submitting || sourceManagementHasActiveRequest()));
      button.textContent = recovery.label;
      actions.append(button);
    }
    for (const action of entry.availableActions || []) {
      const button = document.createElement("button");
      button.type = "button";
      button.className = `button button-compact write-action${action === "purge" ? " button-danger" : ""}`;
      button.dataset.slimmingRecycleEntryId = entry.id;
      button.dataset.action = action;
      button.dataset.helpDetail = slimmingRecycleDirectActionHelp(entry, action);
      button.disabled = recycle.mutatingEntryIDs.has(entry.id);
      button.textContent = slimmingRecycleDirectActionLabel(entry, action);
      actions.append(button);
    }
    if (slimmingRecycleShowsExplanation(entry)) {
      const explanation = document.createElement("button");
      explanation.type = "button";
      explanation.className = "button button-compact";
      explanation.dataset.slimmingRecycleExplanationId = entry.id;
      explanation.dataset.helpDetail = "说明本次操作为何未完成，以及下一步如何处理。";
      explanation.textContent = "说明";
      actions.append(explanation);
    }
    row.append(thumbnail, copy, policy, actions);
    elements.slimmingRecycleList.append(row);
  }
  renderSlimmingRecycleRequest();
  syncWriteActionControls();
}

function scheduleSlimmingRecyclePoll() {
  clearTimeout(state.slimming.recycle.pollTimer);
  state.slimming.recycle.pollTimer = null;
  if (elements.slimmingWorkspace.classList.contains("hidden")
    || state.slimming.view !== "recycle") return;
  const active = state.slimming.recycle.requests.some(
    (request) => ["awaitingMac", "running"].includes(request.phase)
  );
  if (!active) return;
  state.slimming.recycle.pollTimer = setTimeout(() => {
    loadSlimmingRecycle({ quiet: true });
  }, 1000);
}

async function loadSlimmingRecycle({ quiet = false } = {}) {
  const recycle = state.slimming.recycle;
  const generation = ++recycle.requestGeneration;
  recycle.loading = true;
  renderSlimmingWorkspace();
  const query = new URLSearchParams({
    mediaKind: state.slimming.mediaKind,
    scope: recycle.scope,
    limit: String(recycle.limit),
  });
  if (recycle.sourceID) query.set("sourceID", recycle.sourceID);
  if (recycle.searchText.trim()) query.set("search", recycle.searchText.trim());
  try {
    const snapshot = await api(`/v1/library-slimming/recycle?${query}`);
    if (generation !== recycle.requestGeneration) return;
    recycle.entries = snapshot.entries || [];
    recycle.totalCount = snapshot.totalCount || 0;
    recycle.requests = snapshot.requests || [];
    if (snapshot.scopeCounts) {
      recycle.scopeSupported = true;
      recycle.scopeCounts = {
        all: Number(snapshot.scopeCounts.all || 0),
        photos: Number(snapshot.scopeCounts.photos || 0),
        files: Number(snapshot.scopeCounts.files || 0),
        attention: Number(snapshot.scopeCounts.attention || 0),
      };
    } else {
      recycle.scopeSupported = false;
      recycle.scope = "all";
      recycle.scopeCounts = {
        all: recycle.totalCount,
        photos: 0,
        files: 0,
        attention: 0,
      };
    }
  } catch (error) {
    if (generation === recycle.requestGeneration && !quiet) {
      toast(error.message || "回收站载入失败");
    }
  } finally {
    if (generation === recycle.requestGeneration) {
      recycle.loading = false;
      renderSlimmingWorkspace();
      scheduleSlimmingRecyclePoll();
    }
  }
}

async function submitSlimmingRecycleAction(entryID, action, { confirmed = false } = {}) {
  const entry = state.slimming.recycle.entries.find((item) => item.id === entryID);
  if (!entry || state.slimming.recycle.mutatingEntryIDs.has(entryID)) return;
  if (!confirmed && ["purge", "discardPreflightFailure"].includes(action)) {
    const purge = action === "purge";
    requestConfirmation({
      eyebrow: purge ? "PERMANENT DELETE" : "RECYCLE RECORD",
      title: purge
        ? `永久删除“${entry.fileName || "未命名媒体"}”？`
        : "撤销这条未执行的失败记录？",
      message: purge
        ? "网页提交后还必须在 Mac 上再次确认。操作完成后将无法从 ImageAll 恢复。"
        : "只移除失败意图，不会读取、移动、覆盖或删除原文件。",
      actionLabel: purge ? "继续删除" : "撤销失败记录",
      tone: purge ? "danger" : "standard",
      returnFocus: { recycleEntryID: entryID },
      action: () => submitSlimmingRecycleAction(entryID, action, { confirmed: true }),
    });
    return;
  }
  state.slimming.recycle.mutatingEntryIDs.add(entryID);
  renderSlimmingRecycle();
  try {
    const request = await api("/v1/library-slimming/recycle/requests", {
      method: "POST",
      body: JSON.stringify({ operationID: crypto.randomUUID(), entryID, action }),
    });
    state.slimming.recycle.requests = [
      request,
      ...state.slimming.recycle.requests.filter((item) => item.id !== request.id),
    ];
    toast(request.phase === "awaitingMac" ? "请回到 Mac 完成确认" : request.message);
  } catch (error) {
    toast(error.message || "回收站操作提交失败");
  } finally {
    state.slimming.recycle.mutatingEntryIDs.delete(entryID);
    renderSlimmingRecycle();
    scheduleSlimmingRecyclePoll();
  }
}

async function submitSlimmingRecycleRecoveryAction(entryID, action) {
  const recycle = state.slimming.recycle;
  const entry = recycle.entries.find((item) => item.id === entryID);
  if (!entry
    || recycle.mutatingEntryIDs.has(entryID)
    || state.sourceManagement.submitting
    || sourceManagementHasActiveRequest()) return;
  const scrollTop = elements.slimmingRecycleBody.scrollTop;
  recycle.mutatingEntryIDs.add(entryID);
  renderSlimmingRecycle();
  try {
    await submitSourceManagementAction(action, entry.sourceID);
  } finally {
    recycle.mutatingEntryIDs.delete(entryID);
    renderSlimmingRecycle();
    elements.slimmingRecycleBody.scrollTop = scrollTop;
    requestAnimationFrame(() => {
      const focusTarget = elements.slimmingRecycleList.querySelector(
        `[data-slimming-recycle-entry-id="${CSS.escape(entryID)}"]`
      );
      focusTarget?.focus({ preventScroll: true });
    });
  }
}

async function setSlimmingView(view) {
  if (!['analysis', 'recycle'].includes(view) || view === state.slimming.view) return;
  finishSlimmingMarqueeSelection();
  hideContextMenus();
  state.slimming.selectionMode = false;
  state.slimming.view = view;
  renderSlimmingWorkspace();
  if (view === "recycle") await loadSlimmingRecycle();
  else {
    await loadSlimmingWorkspace();
    await loadSlimmingRemovals({ quiet: true });
    await loadSlimmingIdenticalCleanupRequests({ quiet: true });
  }
}

function renderSlimmingNavigator() {
  const analysisView = state.slimming.view === "analysis";
  const visible = state.slimming.navigatorVisible;
  elements.slimmingNavigatorButton.classList.toggle("hidden", !analysisView);
  elements.slimmingNavigatorButton.setAttribute("aria-pressed", String(visible));
  elements.slimmingNavigatorButton.setAttribute(
    "aria-label",
    visible ? "隐藏分析记录" : "显示分析记录"
  );
  elements.slimmingNavigatorButton.title = visible
    ? "隐藏分析记录与候选分组，让媒体网格使用全部宽度"
    : "显示分析记录与候选分组";
  elements.slimmingAnalysisBody.classList.toggle("navigator-hidden", !visible);
}

function toggleSlimmingNavigator() {
  state.slimming.navigatorVisible = !state.slimming.navigatorVisible;
  renderSlimmingNavigator();
  elements.slimmingNavigatorButton.focus({ preventScroll: true });
}

function renderSlimmingWorkspace() {
  const recycleView = state.slimming.view === "recycle";
  renderSlimmingNavigator();
  elements.slimmingThumbnailLayoutControls.classList.toggle("recycle-view", recycleView);
  for (const button of elements.slimmingWorkspaceTabs.querySelectorAll("[data-slimming-view]")) {
    button.setAttribute("aria-pressed", String(button.dataset.slimmingView === state.slimming.view));
  }
  for (const button of elements.slimmingMediaKindTabs.querySelectorAll(
    "[data-slimming-media-kind]"
  )) {
    button.setAttribute(
      "aria-pressed",
      String(button.dataset.slimmingMediaKind === state.slimming.mediaKind)
    );
  }
  elements.slimmingAnalysisBody.classList.toggle("hidden", recycleView);
  elements.slimmingRecycleBody.classList.toggle("hidden", !recycleView);
  elements.newSlimmingAnalysisButton.classList.toggle("hidden", recycleView);
  const identicalGroupCount = state.slimming.clusters.filter(
    (cluster) => cluster.kind === "byteIdentical"
  ).length;
  const identicalActive = currentSlimmingIdenticalCleanupRequest();
  const analysisBlocksIdenticalCleanup = state.slimming.jobs.some(
    (job) => ["pending", "running"].includes(job.state)
  );
  elements.slimmingIdenticalCleanupButton.classList.toggle(
    "hidden",
    recycleView || identicalGroupCount === 0
  );
  elements.slimmingIdenticalCleanupButton.disabled = state.slimming.loading
    || state.slimming.identicalCleanup.preparing
    || state.slimming.identicalCleanup.submitting
    || analysisBlocksIdenticalCleanup
    || ["awaitingMac", "running"].includes(identicalActive?.phase);
  elements.slimmingIdenticalCleanupButton.textContent = identicalGroupCount
    ? `一键清理完全相同（${identicalGroupCount} 组）…`
    : "一键清理完全相同…";
  elements.slimmingIdenticalCleanupButton.setAttribute(
    "aria-label",
    identicalGroupCount
      ? `一键清理完全相同，共 ${identicalGroupCount} 组`
      : "一键清理完全相同"
  );
  elements.slimmingIdenticalCleanupButton.title = analysisBlocksIdenticalCleanup
    ? "请先等待当前分析完成或暂停"
    : "按 Mac 端规则为每个完全相同分组保留一项，并预览其余项目的清理方案";
  const loading = recycleView ? state.slimming.recycle.loading : state.slimming.loading;
  elements.refreshSlimmingButton.disabled = loading;
  elements.refreshSlimmingButton.setAttribute("aria-busy", String(loading));
  const noun = state.slimming.mediaKind === "video" ? "视频" : "照片";
  elements.slimmingNoticeText.textContent = recycleView
    ? "回收站状态来自这台 Mac；恢复、重新协调和永久删除必须在 Mac 原生窗口确认。Apple Photos 仍由系统“照片”App 管理。"
    : "分析与任务控制由这台 Mac 执行；网页只接收结果。";
  elements.slimmingSummary.textContent = recycleView
    ? (state.slimming.recycle.loading
      ? `正在读取${noun}回收站…`
      : `${state.slimming.recycle.totalCount} 个${noun}回收项目`)
    : (state.slimming.loading
      ? `正在读取${noun}分析记录…`
      : `${state.slimming.jobs.length} 条记录 · ${state.slimming.jobs.find((job) => job.id === state.slimming.selectedJobID)?.clusterCount || 0} 个候选分组`);
  if (recycleView) {
    renderSlimmingRecycle();
    return;
  }
  renderSlimmingJobs();
  renderSlimmingClusters();
  renderSlimmingMembers();
  renderSlimmingInspector();
  renderSlimmingJobStatus();
  renderSlimmingRemovalStatus();
}

function scheduleSlimmingRemovalPoll() {
  clearTimeout(state.slimming.removal.pollTimer);
  state.slimming.removal.pollTimer = null;
  const active = state.slimming.removal.requests.some(
    (request) => request.phase === "awaitingMac" || request.phase === "running"
  );
  if (!active || elements.slimmingWorkspace.classList.contains("hidden")) return;
  state.slimming.removal.pollTimer = setTimeout(
    () => loadSlimmingRemovals({ quiet: true }),
    900
  );
}

async function loadSlimmingRemovals({ quiet = false } = {}) {
  const generation = ++state.slimming.removal.requestGeneration;
  const previouslyActiveIDs = new Set(
    state.slimming.removal.requests
      .filter((request) => request.phase === "awaitingMac" || request.phase === "running")
      .map((request) => request.id)
  );
  state.slimming.removal.loading = true;
  try {
    const query = new URLSearchParams({ mediaKind: state.slimming.mediaKind });
    const snapshot = await api(`/v1/library-slimming/removals?${query}`);
    if (generation !== state.slimming.removal.requestGeneration) return;
    state.slimming.removal.requests = snapshot.requests || [];
    const terminal = state.slimming.removal.requests.find((request) =>
      previouslyActiveIDs.has(request.id)
        && ["completed", "cancelled", "failed"].includes(request.phase)
    );
    if (terminal && terminal.id !== state.slimming.removal.lastTerminalRequestID) {
      state.slimming.removal.lastTerminalRequestID = terminal.id;
      const hidden = new Set(terminal.audit?.hiddenAssetIDs || []);
      if (hidden.size) {
        state.slimming.members = state.slimming.members.filter((member) => !hidden.has(member.id));
        state.slimming.selectedMemberIDs = new Set(
          [...state.slimming.selectedMemberIDs].filter((id) => !hidden.has(id))
        );
      }
      toast(terminal.message || "批量操作已结束");
      if (terminal.phase === "completed") {
        await loadSlimmingWorkspace({ quiet: true });
      }
      reconcileSlimmingPreviewAfterRemoval(terminal, hidden);
    }
  } catch (error) {
    if (generation === state.slimming.removal.requestGeneration && !quiet) {
      toast(error.message || "批量操作状态载入失败");
    }
  } finally {
    if (generation === state.slimming.removal.requestGeneration) {
      state.slimming.removal.loading = false;
      renderSlimmingWorkspace();
      scheduleSlimmingRemovalPoll();
    }
  }
}

function replacementSlimmingPreviewAssetID(previousIDs, remainingIDs, previewAssetID) {
  if (remainingIDs.includes(previewAssetID)) return previewAssetID;
  const previousIndex = previousIDs.indexOf(previewAssetID);
  if (previousIndex < 0) return null;
  const remaining = new Set(remainingIDs);
  for (let index = previousIndex + 1; index < previousIDs.length; index += 1) {
    if (remaining.has(previousIDs[index])) return previousIDs[index];
  }
  for (let index = previousIndex - 1; index >= 0; index -= 1) {
    if (remaining.has(previousIDs[index])) return previousIDs[index];
  }
  return null;
}

function reconcileSlimmingPreviewAfterRemoval(request, hiddenAssetIDs) {
  const context = state.slimming.removal.previewContexts.get(request.id);
  if (!context) return;
  state.slimming.removal.previewContexts.delete(request.id);
  if (!hiddenAssetIDs.has(context.assetID)) return;
  const remainingIDs = state.slimming.selectedClusterID === context.clusterID
    ? state.slimming.members.map((member) => member.id)
    : [];
  const replacementID = replacementSlimmingPreviewAssetID(
    context.memberIDs,
    remainingIDs,
    context.assetID
  );
  state.slimming.selectedMemberIDs = replacementID ? new Set([replacementID]) : new Set();
  state.slimming.selectionAnchorID = replacementID;
  if (state.lightboxContext !== "slimming"
    || state.lightboxAssetID !== context.assetID
    || elements.lightbox.classList.contains("hidden")) return;
  if (!replacementID) {
    closeLightbox();
    return;
  }
  state.lightboxAssetID = replacementID;
  const card = elements.slimmingMemberGrid.querySelector(
    `[data-slimming-member-id="${CSS.escape(replacementID)}"]`
  );
  state.lightboxReturnFocus = slimmingMemberMainButton(card) || state.lightboxReturnFocus;
  renderSlimmingMemberSelection();
  renderLightbox();
}

async function submitSlimmingRemoval(
  mode,
  { assetIDs: requestedAssetIDs = null, previewAssetID = null, confirmed = false } = {}
) {
  const memberIDs = new Set(state.slimming.members.map((member) => member.id));
  const assetIDs = (requestedAssetIDs || [...state.slimming.selectedMemberIDs])
    .filter((id) => memberIDs.has(id) && !activeSlimmingRemovalPhase(id));
  if (!assetIDs.length || !state.slimming.selectedJobID || !state.slimming.selectedClusterID) {
    toast("请先在一个候选分组中选择项目");
    return;
  }
  const noun = state.slimming.mediaKind === "video" ? "段视频" : "张照片";
  const targetCopy = previewAssetID ? "当前预览" : "选中的";
  if (!confirmed) {
    const releasesSpace = mode === "releaseSourceSpace";
    requestConfirmation({
      eyebrow: releasesSpace ? "QUICK DELETE" : "RECOVERABLE RECYCLE",
      title: releasesSpace
        ? `立即处理${targetCopy} ${assetIDs.length} ${noun}？`
        : `移入可恢复回收站？`,
      message: releasesSpace
        ? "文件夹来源会在身份核验后永久删除，无法从 ImageAll 恢复；Apple Photos 项只会进入系统“最近删除”。提交后还需要在 Mac 原生窗口再次确认。"
        : `将${targetCopy} ${assetIDs.length} ${noun}移入回收站。文件夹来源会先复制并校验并保留 30 天；Apple Photos 项会进入系统“最近删除”。提交后还需要在 Mac 原生窗口再次确认。`,
      actionLabel: releasesSpace ? "快速删除" : "可恢复回收",
      tone: releasesSpace ? "danger" : "warning",
      returnFocus: previewAssetID
        ? { lightboxAssetID: previewAssetID, slimmingMemberID: previewAssetID }
        : { element: document.activeElement },
      action: () => submitSlimmingRemoval(mode, {
        assetIDs,
        previewAssetID,
        confirmed: true,
      }),
    });
    return;
  }
  state.slimming.removal.submitting = true;
  const submitsCurrentPreview = Boolean(
    previewAssetID
      && state.lightboxContext === "slimming"
      && state.lightboxAssetID === previewAssetID
      && !elements.lightbox.classList.contains("hidden")
  );
  if (submitsCurrentPreview) elements.lightboxDeleteButton.disabled = true;
  renderSlimmingMemberSelection();
  try {
    const request = await api("/v1/library-slimming/removals", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        jobID: state.slimming.selectedJobID,
        clusterID: state.slimming.selectedClusterID,
        mediaKind: state.slimming.mediaKind,
        assetIDs,
        mode,
      }),
    });
    state.slimming.removal.requests = [
      request,
      ...state.slimming.removal.requests.filter((item) => item.id !== request.id),
    ];
    if (previewAssetID) {
      state.slimming.removal.previewContexts.set(request.id, {
        assetID: previewAssetID,
        clusterID: state.slimming.selectedClusterID,
        memberIDs: state.slimming.members.map((member) => member.id),
      });
    }
    toast("已冻结本次选区，请回到 Mac 核对并确认");
  } catch (error) {
    toast(error.message || "批量操作提交失败");
  } finally {
    state.slimming.removal.submitting = false;
    renderSlimmingWorkspace();
    if (submitsCurrentPreview) renderLightbox();
    scheduleSlimmingRemovalPoll();
  }
}

function identicalCleanupPlanCount(plan, key) {
  if (!plan || !Object.prototype.hasOwnProperty.call(plan, key)) return null;
  const value = Number(plan[key]);
  if (!Number.isFinite(value) || value < 0) return null;
  return Math.trunc(value);
}

function appendIdenticalCleanupMetric(label, value, tone, symbol) {
  const card = document.createElement("div");
  card.className = `identical-cleanup-metric ${tone || ""}`;
  const title = document.createElement("span");
  title.className = "identical-cleanup-metric-label";
  if (symbol) {
    const icon = document.createElement("span");
    icon.className = "identical-cleanup-metric-symbol";
    icon.setAttribute("aria-hidden", "true");
    icon.textContent = symbol;
    title.append(icon);
  }
  title.append(document.createTextNode(label));
  const count = document.createElement("strong");
  count.textContent = value === null ? "—" : value.toLocaleString();
  card.append(title, count);
  elements.slimmingIdenticalCleanupMetrics.append(card);
}

function renderIdenticalCleanupDispositionChart(plan) {
  const container = elements.slimmingIdenticalCleanupDispositionChart;
  clearElement(container);
  const retained = identicalCleanupPlanCount(plan, "retainedAssetCount") || 0;
  const removal = identicalCleanupPlanCount(plan, "removalAssetCount") || 0;
  const verified = identicalCleanupPlanCount(plan, "verifiedAssetCount") || 0;
  const dispositionTotal = retained + removal;
  const retainedAngle = dispositionTotal > 0 ? (retained / dispositionTotal) * 360 : 360;

  const chart = document.createElement("div");
  chart.className = "identical-cleanup-donut";
  chart.style.setProperty("--retained-angle", `${retainedAngle}deg`);
  const center = document.createElement("span");
  center.className = "identical-cleanup-donut-center";
  const total = document.createElement("strong");
  total.textContent = verified.toLocaleString();
  const caption = document.createElement("span");
  caption.textContent = "张已核验";
  center.append(total, caption);
  chart.append(center);

  const legend = document.createElement("div");
  legend.className = "identical-cleanup-chart-legend";
  for (const [label, value, tone] of [
    ["保留", retained, "retained"],
    ["清理", removal, "removal"],
  ]) {
    const item = document.createElement("span");
    item.className = tone;
    const dot = document.createElement("i");
    dot.setAttribute("aria-hidden", "true");
    const text = document.createElement("span");
    text.textContent = `${label} ${value.toLocaleString()}`;
    item.append(dot, text);
    legend.append(item);
  }
  container.append(chart, legend);
  container.setAttribute(
    "aria-label",
    `去留比例：已核验 ${verified.toLocaleString()} 张，保留 ${retained.toLocaleString()} 张，清理 ${removal.toLocaleString()} 张`
  );
}

function renderIdenticalCleanupGroupHistogram(plan) {
  const container = elements.slimmingIdenticalCleanupGroupHistogram;
  clearElement(container);
  const buckets = new Map([["2", 0], ["3", 0], ["4", 0], ["5+", 0]]);
  for (const [rawMemberCount, rawGroupCount] of Object.entries(plan.groupSizeHistogram || {})) {
    const memberCount = Number(rawMemberCount);
    const groupCount = Number(rawGroupCount);
    if (!Number.isFinite(memberCount) || !Number.isFinite(groupCount) || groupCount <= 0) continue;
    const label = memberCount >= 5 ? "5+" : String(Math.trunc(memberCount));
    if (buckets.has(label)) buckets.set(label, buckets.get(label) + Math.trunc(groupCount));
  }
  const visibleBuckets = [...buckets.entries()].filter(([, count]) => count > 0);
  const maxCount = Math.max(1, ...visibleBuckets.map(([, count]) => count));
  if (!visibleBuckets.length) {
    const empty = document.createElement("p");
    empty.className = "identical-cleanup-chart-empty";
    empty.textContent = "当前 Host 未提供分组规模分布。";
    container.append(empty);
  } else {
    for (const [label, count] of visibleBuckets) {
      const column = document.createElement("div");
      column.className = "identical-cleanup-histogram-column";
      const value = document.createElement("strong");
      value.textContent = count.toLocaleString();
      const track = document.createElement("span");
      track.className = "identical-cleanup-histogram-track";
      const bar = document.createElement("span");
      bar.className = "identical-cleanup-histogram-bar";
      bar.style.setProperty("--bar-ratio", String(count / maxCount));
      track.append(bar);
      const bucket = document.createElement("span");
      bucket.className = "identical-cleanup-histogram-label";
      bucket.textContent = label;
      column.append(value, track, bucket);
      container.append(column);
    }
  }
  const summary = visibleBuckets.map(([label, count]) => `每组 ${label} 项有 ${count} 组`).join("，");
  container.setAttribute("aria-label", `完全相同组规模分布${summary ? `：${summary}` : "不可用"}`);
}

function renderIdenticalCleanupSourceChart(plan) {
  const container = elements.slimmingIdenticalCleanupSources;
  clearElement(container);
  const sources = [
    ["Apple Photos", identicalCleanupPlanCount(plan, "photosAssetCount") || 0, "photos"],
    ["文件夹来源", identicalCleanupPlanCount(plan, "fileAssetCount") || 0, "files"],
  ];
  const maxCount = Math.max(1, ...sources.map(([, count]) => count));
  for (const [label, count, tone] of sources) {
    const row = document.createElement("div");
    row.className = `identical-cleanup-source-row ${tone}`;
    const term = document.createElement("dt");
    term.textContent = label;
    const description = document.createElement("dd");
    const track = document.createElement("span");
    track.className = "identical-cleanup-source-track";
    const bar = document.createElement("span");
    bar.className = "identical-cleanup-source-bar";
    bar.style.setProperty("--source-ratio", String(count / maxCount));
    track.append(bar);
    const value = document.createElement("strong");
    value.textContent = `${count.toLocaleString()} 张`;
    description.append(track, value);
    row.append(term, description);
    container.append(row);
  }
  container.setAttribute(
    "aria-label",
    `待清理媒体来源：Apple Photos ${sources[0][1].toLocaleString()} 张，文件夹来源 ${sources[1][1].toLocaleString()} 张`
  );
}

function appendIdenticalCleanupNotice(message, tone, symbol) {
  const notice = document.createElement("p");
  notice.className = tone || "";
  if (symbol) {
    const icon = document.createElement("span");
    icon.setAttribute("aria-hidden", "true");
    icon.textContent = symbol;
    notice.append(icon);
  }
  notice.append(document.createTextNode(message));
  elements.slimmingIdenticalCleanupNotice.append(notice);
}

function renderSlimmingIdenticalCleanupDialog() {
  const cleanup = state.slimming.identicalCleanup;
  elements.slimmingIdenticalCleanupLoading.classList.toggle("hidden", !cleanup.preparing);
  elements.slimmingIdenticalCleanupContent.classList.toggle(
    "hidden",
    cleanup.preparing || !cleanup.plan
  );
  elements.slimmingIdenticalCleanupError.textContent = cleanup.error || "";
  clearElement(elements.slimmingIdenticalCleanupMetrics);
  elements.slimmingIdenticalCleanupRetentionSummary.textContent = "";
  clearElement(elements.slimmingIdenticalCleanupDispositionChart);
  clearElement(elements.slimmingIdenticalCleanupGroupHistogram);
  clearElement(elements.slimmingIdenticalCleanupSources);
  clearElement(elements.slimmingIdenticalCleanupNotice);
  const plan = cleanup.plan;
  if (plan) {
    const favoriteRetained = identicalCleanupPlanCount(plan, "favoriteRetainedAssetCount");
    const ordinaryRetained = identicalCleanupPlanCount(plan, "ordinaryRetainedAssetCount");
    const protectedSkipped = identicalCleanupPlanCount(plan, "protectedSkippedAssetCount");
    appendIdenticalCleanupMetric(
      "已核验媒体", identicalCleanupPlanCount(plan, "verifiedAssetCount"), "blue", "✓"
    );
    appendIdenticalCleanupMetric(
      "会保留", identicalCleanupPlanCount(plan, "retainedAssetCount"), "green", "▣"
    );
    appendIdenticalCleanupMetric("红心保留", favoriteRetained, "red", "♥");
    appendIdenticalCleanupMetric(
      "将清理", identicalCleanupPlanCount(plan, "removalAssetCount"), "orange", "⌫"
    );
    appendIdenticalCleanupMetric(
      "处理分组", identicalCleanupPlanCount(plan, "groupCount"), "indigo", "▤"
    );
    if (favoriteRetained !== null && ordinaryRetained !== null && protectedSkipped !== null) {
      elements.slimmingIdenticalCleanupRetentionSummary.textContent =
        `普通保留 ${ordinaryRetained.toLocaleString()} 项；全组红心而安全跳过 ${protectedSkipped.toLocaleString()} 项。红心资产不会进入自动删除计划。`;
    } else {
      elements.slimmingIdenticalCleanupRetentionSummary.textContent =
        "当前 Mac Host 未提供红心保护拆分；执行计划仍由 Mac 按红心保护规则逐项核验。";
    }
    renderIdenticalCleanupDispositionChart(plan);
    renderIdenticalCleanupGroupHistogram(plan);
    renderIdenticalCleanupSourceChart(plan);

    const fileAssetCount = identicalCleanupPlanCount(plan, "fileAssetCount") || 0;
    const photosAssetCount = identicalCleanupPlanCount(plan, "photosAssetCount") || 0;
    const skippedGroupCount = identicalCleanupPlanCount(plan, "skippedGroupCount") || 0;
    if (fileAssetCount > 0) {
      appendIdenticalCleanupNotice(
        `“快速清理”会永久删除 ${fileAssetCount.toLocaleString()} 个文件夹媒体，ImageAll 无法恢复。`,
        "danger",
        "!"
      );
    }
    if (photosAssetCount > 0) {
      appendIdenticalCleanupNotice(
        "macOS 仍会对全部 Apple Photos 待删项集中显示一次系统确认。",
        "warning",
        "△"
      );
    }
    if (skippedGroupCount > 0) {
      appendIdenticalCleanupNotice(
        `另有 ${skippedGroupCount.toLocaleString()} 组因成员或来源状态变化已安全跳过，不会删除。`,
        "warning",
        "◇"
      );
    }
    if (!elements.slimmingIdenticalCleanupNotice.childElementCount) {
      appendIdenticalCleanupNotice(
        "执行前 Mac 还会再次核验冻结方案，变化的项目不会被删除。",
        "safe",
        "✓"
      );
    }
  }
  const disabled = cleanup.preparing || cleanup.submitting || !plan;
  elements.recoverableSlimmingIdenticalCleanupButton.disabled = disabled;
  elements.fastSlimmingIdenticalCleanupButton.disabled = disabled;
  elements.recoverableSlimmingIdenticalCleanupButton.textContent = plan
    ? `可恢复回收 ${plan.removalAssetCount} 项`
    : "可恢复回收";
  elements.fastSlimmingIdenticalCleanupButton.textContent = plan
    ? `快速清理 ${plan.removalAssetCount} 项`
    : "快速清理";
}

async function openSlimmingIdenticalCleanupDialog() {
  if (!state.slimming.selectedJobID || state.slimming.identicalCleanup.preparing) return;
  const cleanup = state.slimming.identicalCleanup;
  cleanup.plan = null;
  cleanup.error = "";
  cleanup.preparing = true;
  elements.slimmingIdenticalCleanupDialog.showModal();
  renderSlimmingIdenticalCleanupDialog();
  try {
    cleanup.plan = await api("/v1/library-slimming/identical-cleanup/plans", {
      method: "POST",
      body: JSON.stringify({
        jobID: state.slimming.selectedJobID,
        mediaKind: state.slimming.mediaKind,
      }),
    });
  } catch (error) {
    cleanup.error = error.message || "无法生成一键清理方案";
  } finally {
    cleanup.preparing = false;
    renderSlimmingIdenticalCleanupDialog();
  }
}

function closeSlimmingIdenticalCleanupDialog() {
  if (state.slimming.identicalCleanup.submitting) return;
  if (elements.slimmingIdenticalCleanupDialog.open) {
    elements.slimmingIdenticalCleanupDialog.close();
  }
  state.slimming.identicalCleanup.plan = null;
  state.slimming.identicalCleanup.error = "";
}

async function submitSlimmingIdenticalCleanup(mode) {
  const cleanup = state.slimming.identicalCleanup;
  if (!cleanup.plan || cleanup.submitting) return;
  cleanup.submitting = true;
  cleanup.error = "";
  renderSlimmingIdenticalCleanupDialog();
  try {
    const request = await api("/v1/library-slimming/identical-cleanup/requests", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        planID: cleanup.plan.id,
        mode,
      }),
    });
    cleanup.requests = [
      request,
      ...cleanup.requests.filter((item) => item.id !== request.id),
    ];
    elements.slimmingIdenticalCleanupDialog.close();
    cleanup.plan = null;
    toast("方案已冻结，请回到 Mac 核对并确认");
    renderSlimmingWorkspace();
    scheduleSlimmingIdenticalCleanupPoll();
  } catch (error) {
    cleanup.error = error.message || "一键清理提交失败";
  } finally {
    cleanup.submitting = false;
    renderSlimmingIdenticalCleanupDialog();
  }
}

function scheduleSlimmingIdenticalCleanupPoll() {
  const cleanup = state.slimming.identicalCleanup;
  clearTimeout(cleanup.pollTimer);
  cleanup.pollTimer = null;
  const active = cleanup.requests.some(
    (request) => request.phase === "awaitingMac" || request.phase === "running"
  );
  if (!active || elements.appView.classList.contains("hidden")) return;
  cleanup.pollTimer = setTimeout(
    () => loadSlimmingIdenticalCleanupRequests({ quiet: true }),
    900
  );
}

async function loadSlimmingIdenticalCleanupRequests({ quiet = false } = {}) {
  const cleanup = state.slimming.identicalCleanup;
  const generation = ++cleanup.requestGeneration;
  const previouslyActiveIDs = new Set(cleanup.requests
    .filter((request) => request.phase === "awaitingMac" || request.phase === "running")
    .map((request) => request.id));
  try {
    const snapshots = await Promise.all(["image", "video"].map((mediaKind) => {
      const query = new URLSearchParams({ mediaKind });
      return api(`/v1/library-slimming/identical-cleanup/requests?${query}`);
    }));
    if (generation !== cleanup.requestGeneration) return;
    const merged = new Map();
    for (const request of snapshots.flatMap((snapshot) => snapshot.requests || [])) {
      const existing = merged.get(request.id);
      if (!existing || Number(request.updatedAtMs || 0) > Number(existing.updatedAtMs || 0)) {
        merged.set(request.id, request);
      }
    }
    cleanup.requests = [...merged.values()].sort(
      (left, right) => Number(right.updatedAtMs || 0) - Number(left.updatedAtMs || 0)
    );
    renderIdenticalCleanupBlockingOverlay();
    const terminal = cleanup.requests.find((request) =>
      previouslyActiveIDs.has(request.id)
        && ["completed", "cancelled", "failed"].includes(request.phase));
    if (terminal && terminal.id !== cleanup.lastTerminalRequestID) {
      cleanup.lastTerminalRequestID = terminal.id;
      toast(terminal.message || "一键清理已结束");
      if (terminal.verification && terminal.id !== cleanup.lastPresentedVerificationID) {
        cleanup.lastPresentedVerificationID = terminal.id;
        openSlimmingVerificationReport(terminal);
      }
      if (terminal.phase === "completed") {
        await loadSlimmingWorkspace({ quiet: true });
        await loadSlimmingRemovals({ quiet: true });
      }
    }
  } catch (error) {
    if (generation === cleanup.requestGeneration && !quiet) {
      toast(error.message || "一键清理状态载入失败");
    }
  } finally {
    if (generation === cleanup.requestGeneration) {
      renderSlimmingWorkspace();
      renderIdenticalCleanupBlockingOverlay();
      scheduleSlimmingIdenticalCleanupPoll();
    }
  }
}

async function loadSlimmingWorkspace({ jobID = null, clusterID = null, quiet = false } = {}) {
  if (jobID || clusterID) state.slimming.selectionMode = false;
  const generation = ++state.slimming.requestGeneration;
  const previousSelectedMemberIDs = new Set(state.slimming.selectedMemberIDs);
  const previousSelectionAnchorID = state.slimming.selectionAnchorID;
  state.slimming.loading = true;
  renderSlimmingWorkspace();
  const query = new URLSearchParams({ mediaKind: state.slimming.mediaKind });
  query.set("clusterScope", state.slimming.clusterScope);
  query.set("jobLimit", String(state.slimming.jobLimit));
  query.set("clusterLimit", String(state.slimming.clusterLimit));
  query.set("memberLimit", String(state.slimming.memberLimit));
  if (jobID || state.slimming.selectedJobID) query.set("jobID", jobID || state.slimming.selectedJobID);
  if (clusterID || state.slimming.selectedClusterID) {
    query.set("clusterID", clusterID || state.slimming.selectedClusterID);
  }
  try {
    const snapshot = await api(`/v1/library-slimming/workspace?${query}`);
    if (generation !== state.slimming.requestGeneration) return false;
    state.slimming.jobs = snapshot.jobs || [];
    state.slimming.totalJobCount = Number(snapshot.totalJobCount ?? state.slimming.jobs.length);
    // Deep links may cause the Host to grow the prefix through the requested job.
    // Preserve that authoritative window on later refreshes.
    state.slimming.jobLimit = Math.max(state.slimming.jobLimit, state.slimming.jobs.length);
    state.slimming.selectedJobID = snapshot.selectedJobID || null;
    state.slimming.clusters = snapshot.clusters || [];
    state.slimming.selectedClusterID = snapshot.selectedClusterID || null;
    state.slimming.members = snapshot.members || [];
    if (snapshot.clusterScopeCounts) {
      state.slimming.clusterScopeSupported = true;
      state.slimming.clusterScopeCounts = {
        pending: Number(snapshot.clusterScopeCounts.pending || 0),
        confirmed: Number(snapshot.clusterScopeCounts.confirmed || 0),
        ignored: Number(snapshot.clusterScopeCounts.ignored || 0),
      };
    } else {
      state.slimming.clusterScopeSupported = false;
      state.slimming.clusterScope = "pending";
      const selectedJob = state.slimming.jobs.find(
        (candidate) => candidate.id === state.slimming.selectedJobID
      );
      state.slimming.clusterScopeCounts = {
        pending: Number(selectedJob?.clusterCount || state.slimming.clusters.length),
        confirmed: 0,
        ignored: 0,
      };
    }
    state.slimming.pendingAnalysisCount = snapshot.pendingAnalysisCount || 0;
    state.slimming.analyzedAssetCount = snapshot.analyzedAssetCount || 0;
    state.slimming.policyVersion = snapshot.policyVersion || null;
    const memberIDs = new Set(state.slimming.members.map((member) => member.id));
    state.slimming.selectedMemberIDs = (jobID || clusterID)
      ? new Set()
      : new Set([...previousSelectedMemberIDs].filter((id) => memberIDs.has(id)));
    state.slimming.selectionAnchorID = state.slimming.selectedMemberIDs.has(
      previousSelectionAnchorID
    ) ? previousSelectionAnchorID : null;
    return true;
  } catch (error) {
    if (generation === state.slimming.requestGeneration && !quiet) {
      toast(error.message || "图库瘦身结果载入失败");
    }
    return false;
  } finally {
    if (generation === state.slimming.requestGeneration) {
      state.slimming.loading = false;
      renderSlimmingWorkspace();
    }
  }
}

async function selectSlimmingClusterScope(scope, { focus = true } = {}) {
  if (!["pending", "confirmed", "ignored"].includes(scope)
    || state.slimming.loading
    || (state.slimming.clusterScopeSupported === false && scope !== "pending")) return;
  if (scope === state.slimming.clusterScope) {
    if (focus) {
      elements.slimmingClusterScopes.querySelector(
        `[data-slimming-cluster-scope="${CSS.escape(scope)}"]`
      )?.focus({ preventScroll: true });
    }
    return;
  }
  state.slimming.clusterScope = scope;
  state.slimming.selectedClusterID = null;
  state.slimming.selectedMemberIDs.clear();
  state.slimming.selectionAnchorID = null;
  state.slimming.clusterLimit = 48;
  state.slimming.memberLimit = 96;
  await loadSlimmingWorkspace({ quiet: true });
  if (focus) {
    elements.slimmingClusterScopes.querySelector(
      `[data-slimming-cluster-scope="${CSS.escape(state.slimming.clusterScope)}"]`
    )?.focus({ preventScroll: true });
  }
}

async function setSlimmingClusterReviewDisposition(clusterID, disposition) {
  if (!state.online
    || state.slimming.clusterScopeSupported !== true
    || !state.slimming.selectedJobID
    || !clusterID
    || state.slimming.clusterReviewPendingIDs.has(clusterID)) return;
  const cluster = state.slimming.clusters.find((candidate) => candidate.id === clusterID);
  if (!cluster) return;
  state.slimming.clusterReviewPendingIDs.add(clusterID);
  renderSlimmingClusters();
  renderSlimmingSelectedClusterReview(cluster);
  try {
    await api("/v1/library-slimming/cluster-review", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        jobID: state.slimming.selectedJobID,
        clusterID,
        disposition,
      }),
    });
    const removesResolvedHistoricalRecord = disposition == null
      && cluster.isHistoricalProcessedRecord
      && Number(cluster.memberCount || 0) < 2;
    toast(disposition === "confirmed"
      ? "已收进确认队列，可随时打开重新处理"
      : disposition === "ignored"
        ? "已收进忽略队列，可随时打开重新处理"
        : removesResolvedHistoricalRecord
          ? "历史记录已移出审阅队列；当前不足两项，无需返回待处理"
          : "已移回待处理队列");
    state.slimming.selectedClusterID = null;
    state.slimming.selectedMemberIDs.clear();
    state.slimming.selectionAnchorID = null;
    await loadSlimmingWorkspace({ quiet: true });
    focusSelectedSlimmingCluster();
  } catch (error) {
    toast(error.message || "分组状态保存失败");
  } finally {
    state.slimming.clusterReviewPendingIDs.delete(clusterID);
    renderSlimmingWorkspace();
  }
}

async function openSlimmingWorkspace({ historyMode = "push" } = {}) {
  elements.reviewWorkspace.classList.add("hidden");
  state.reviewReturnFocus = null;
  elements.trainingWorkspace.classList.add("hidden");
  state.trainingReturnFocus = null;
  closeJobsPopover({ restoreFocus: false });
  elements.filterPopover.classList.add("hidden");
  elements.filterButton.setAttribute("aria-expanded", "false");
  if (elements.slimmingWorkspace.classList.contains("hidden")) {
    state.slimmingReturnFocus = document.activeElement;
  }
  if (matchMedia("(max-width: 720px)").matches
    && !state.slimming.inspectorCompactInitialized) {
    elements.slimmingInspector.open = false;
    state.slimming.inspectorCompactInitialized = true;
  }
  elements.appView.inert = true;
  elements.slimmingWorkspace.classList.remove("hidden");
  recordWorkspaceHistory("slimming", null, historyMode);
  requestAnimationFrame(() => elements.closeSlimmingButton.focus({ preventScroll: true }));
  if (state.slimming.view === "recycle") await loadSlimmingRecycle();
  else {
    await loadSlimmingWorkspace();
    await loadSlimmingRemovals({ quiet: true });
    await loadSlimmingIdenticalCleanupRequests({ quiet: true });
  }
}

async function switchSlimmingMediaKind(mediaKind) {
  if (!["image", "video"].includes(mediaKind)
    || mediaKind === state.slimming.mediaKind) return;
  finishSlimmingMarqueeSelection();
  state.slimming.selectionMode = false;
  state.slimming.mediaKind = mediaKind;
  state.slimming.jobLimit = SLIMMING_JOB_PAGE_SIZE;
  state.slimming.totalJobCount = 0;
  state.slimming.selectedJobID = null;
  state.slimming.selectedClusterID = null;
  state.slimming.selectedMemberIDs.clear();
  state.slimming.selectionAnchorID = null;
  state.slimming.clusterLimit = 48;
  state.slimming.memberLimit = 96;
  state.slimming.recycle.limit = 60;
  state.slimming.removal.requests = [];
  state.slimming.removal.lastTerminalRequestID = null;
  clearTimeout(state.slimming.removal.pollTimer);
  if (state.slimming.view === "recycle") await loadSlimmingRecycle();
  else {
    await Promise.all([
      loadSlimmingWorkspace(),
      loadSlimmingRemovals({ quiet: true }),
      loadSlimmingIdenticalCleanupRequests({ quiet: true }),
    ]);
  }
}

function selectSlimmingMember(
  memberID,
  event = {},
  { focusGrid = false, forceReplace = false } = {}
) {
  const ids = state.slimming.members.map((member) => member.id);
  const additive = !forceReplace
    && (state.slimming.selectionMode || event.metaKey || event.ctrlKey);
  if (event.shiftKey && state.slimming.selectionAnchorID) {
    const anchor = ids.indexOf(state.slimming.selectionAnchorID);
    const target = ids.indexOf(memberID);
    if (anchor >= 0 && target >= 0) {
      const range = ids.slice(Math.min(anchor, target), Math.max(anchor, target) + 1);
      state.slimming.selectedMemberIDs = additive
        ? new Set([...state.slimming.selectedMemberIDs, ...range])
        : new Set(range);
    }
  } else if (additive) {
    if (state.slimming.selectedMemberIDs.has(memberID)) {
      state.slimming.selectedMemberIDs.delete(memberID);
    } else {
      state.slimming.selectedMemberIDs.add(memberID);
    }
    state.slimming.selectionAnchorID = memberID;
  } else {
    state.slimming.selectedMemberIDs = new Set([memberID]);
    state.slimming.selectionAnchorID = memberID;
  }
  renderSlimmingMemberSelection();
  if (focusGrid) {
    const card = elements.slimmingMemberGrid.querySelector(
      `[data-slimming-member-id="${CSS.escape(memberID)}"]`
    );
    card?.scrollIntoView({ block: "nearest", inline: "nearest" });
    slimmingMemberMainButton(card)?.focus({ preventScroll: true });
  }
}

function moveSlimmingMemberSelection(key, { extendRange = false } = {}) {
  if (state.slimming.view !== "analysis" || !state.slimming.members.length) return;
  const ids = state.slimming.members.map((member) => member.id);
  const primaryID = state.slimming.selectionAnchorID
    && state.slimming.selectedMemberIDs.has(state.slimming.selectionAnchorID)
    ? state.slimming.selectionAnchorID
    : [...state.slimming.selectedMemberIDs].find((id) => ids.includes(id));
  const currentIndex = Math.max(0, ids.indexOf(primaryID));
  let nextIndex;
  if (key === "Home") {
    nextIndex = 0;
  } else if (key === "End") {
    nextIndex = ids.length - 1;
  } else {
    const scrollContainer = slimmingMemberScrollContainer();
    const columns = renderedGridColumnCount(
      elements.slimmingMemberGrid,
      ":scope > .slimming-member-card"
    );
    const delta = {
      ArrowLeft: -1,
      ArrowRight: 1,
      ArrowUp: -columns,
      ArrowDown: columns,
      PageUp: -renderedGridPageItemCount(
        scrollContainer,
        elements.slimmingMemberGrid,
        ":scope > .slimming-member-card"
      ),
      PageDown: renderedGridPageItemCount(
        scrollContainer,
        elements.slimmingMemberGrid,
        ":scope > .slimming-member-card"
      ),
    }[key];
    if (!delta) return;
    nextIndex = currentIndex + delta;
  }
  const bounded = Math.max(0, Math.min(ids.length - 1, nextIndex));
  selectSlimmingMember(
    ids[bounded],
    { shiftKey: extendRange },
    { focusGrid: true, forceReplace: true }
  );
}

function currentSlimmingSeedIDs() {
  if (state.mediaKind !== state.slimming.mediaKind) return [];
  if (state.selectedAssetIDs.size) return [...state.selectedAssetIDs];
  return state.selectedAssetID ? [state.selectedAssetID] : [];
}

function currentSlimmingFilterRequest() {
  const accepted = [];
  const rejected = [];
  const excluded = [];
  for (const condition of state.filters.tagConditions) {
    if (condition.decision === "accepted") {
      accepted.push({ tagID: condition.tagID, decision: "accepted" });
    } else if (condition.decision === "rejected") {
      rejected.push({ tagID: condition.tagID, decision: "rejected" });
    } else if (condition.decision === "excluded") {
      excluded.push(condition.tagID);
    }
  }
  return {
    sourceIDs: state.selectedSourceID ? [state.selectedSourceID] : [],
    searchText: state.searchText || null,
    sort: state.sort,
    limit: 200,
    cursor: null,
    tagDecisionFilters: [...accepted, ...rejected],
    excludedTagIDs: excluded,
    tagMatchMode: state.filters.tagMatchMode,
    availabilities: [...state.filters.availabilities],
    mediaKinds: [state.slimming.mediaKind],
    mediaTypes: [...state.filters.mediaTypes],
    tagPresence: state.filters.tagPresence,
  };
}

function slimmingModeCopy(mode) {
  const noun = state.slimming.mediaKind === "video" ? "视频" : "照片";
  return {
    catalog: {
      title: "全部来源",
      detail: `扫描所选来源中的全部可用${noun}`,
    },
    currentFilter: {
      title: "当前筛选",
      detail: `冻结网页图库当前的来源、搜索和标签筛选`,
    },
    seeds: {
      title: "按种子查找",
      detail: `从图库当前选择的${noun}出发查找相似项`,
    },
  }[mode];
}

function slimmingModeAvailable(mode) {
  const setup = state.slimming.setup;
  if (mode === "catalog") return Boolean(setup.snapshot?.sources?.length);
  if (state.mediaKind !== state.slimming.mediaKind) return false;
  if (mode === "seeds") return currentSlimmingSeedIDs().length > 0;
  return true;
}

function normalizeSlimmingThresholdDraft(value) {
  if (!value) return null;
  return {
    featurePrintRecallTopK: Number(value.featurePrintRecallTopK),
    featurePrintMaxL2Distance: Number(value.featurePrintMaxL2Distance),
    dinoCosineMinSimilarity: Number(value.dinoCosineMinSimilarity),
    sceneBucketActivationAssetCount: Number(value.sceneBucketActivationAssetCount),
    featurePrintRecallMode: value.featurePrintRecallMode,
    featurePrintL2Mode: value.featurePrintL2Mode,
    dinoCosineMode: value.dinoCosineMode,
    sceneBucketingMode: value.sceneBucketingMode,
  };
}

function slimmingThresholdsValid(value = state.slimming.setup.thresholds) {
  return Boolean(value)
    && Number.isInteger(value.featurePrintRecallTopK)
    && value.featurePrintRecallTopK > 0
    && value.featurePrintRecallTopK <= 128
    && Number.isFinite(value.featurePrintMaxL2Distance)
    && value.featurePrintMaxL2Distance >= 0
    && value.featurePrintMaxL2Distance <= 200
    && Number.isFinite(value.dinoCosineMinSimilarity)
    && value.dinoCosineMinSimilarity >= 0
    && value.dinoCosineMinSimilarity <= 1
    && Number.isInteger(value.sceneBucketActivationAssetCount)
    && value.sceneBucketActivationAssetCount >= 2
    && value.sceneBucketActivationAssetCount <= 10_000;
}

function resolvedSlimmingCatalogSourceIDs(snapshot) {
  const allSourceIDs = (snapshot?.sources || []).map((source) => source.id);
  if (state.slimming.catalogSourceIDs === null) return new Set(allSourceIDs);
  const available = new Set(allSourceIDs);
  return new Set(
    [...state.slimming.catalogSourceIDs].filter((sourceID) => available.has(sourceID))
  );
}

function setSlimmingCatalogSourceIDs(selectedSourceIDs, snapshot) {
  const allSourceIDs = (snapshot?.sources || []).map((source) => source.id);
  const available = new Set(allSourceIDs);
  const selected = new Set(
    [...selectedSourceIDs].filter((sourceID) => available.has(sourceID))
  );
  state.slimming.catalogSourceIDs = allSourceIDs.length === selected.size
    && allSourceIDs.every((sourceID) => selected.has(sourceID))
    ? null
    : selected;
  state.slimming.setup.selectedSourceIDs = new Set(selected);
  state.slimming.sourceMaintenance.selectedSourceIDs = new Set(selected);
}

function slimmingSourceIndexShortStatus(source) {
  switch (source?.similarityIndex?.state) {
    case "building": return "索引构建中";
    case "ready": return "索引就绪";
    case "stale": return "索引待重建";
    case "failed": return "索引失败";
    default: return "索引未初始化";
  }
}

function slimmingSourceIndexCaption(source, available) {
  if (!available) return "当前 Mac Host 不支持来源相似索引。";
  if (!source) return "来源索引：请选择单个来源";
  const status = source.similarityIndex;
  if (!status) return "来源索引：未初始化";
  switch (status.state) {
    case "building":
      return `来源索引：构建中 ${status.indexedCount}/${status.assetCount}`;
    case "ready":
      return `来源索引：就绪 ${status.indexedCount}/${status.assetCount} · ${status.clusterCount} 簇`;
    case "stale":
      return "来源索引：需要重建";
    case "failed":
      return "来源索引：失败，请重试";
    default:
      return "来源索引：状态不可用";
  }
}

function renderSlimmingSourceMaintenance() {
  const maintenance = state.slimming.sourceMaintenance;
  const snapshot = maintenance.snapshot;
  const sources = snapshot?.sources || [];
  const submitting = Boolean(maintenance.submittingAction);
  elements.slimmingAnalysisOptionsLoading.classList.toggle("hidden", !maintenance.loading);
  elements.slimmingAnalysisOptionsContent.classList.toggle(
    "hidden",
    maintenance.loading || !snapshot
  );
  elements.slimmingAnalysisOptionsError.textContent = maintenance.error;
  clearElement(elements.slimmingMaintenanceSourceOptions);
  if (!snapshot) return;

  const selected = maintenance.selectedSourceIDs;
  const allSelected = sources.length > 0
    && sources.every((source) => selected.has(source.id));
  elements.slimmingMaintenanceSourceSummary.textContent = allSelected
    ? `已选择全部 ${sources.length} 个可用来源。`
    : `已选择 ${selected.size} / ${sources.length} 个来源。`;
  elements.toggleAllSlimmingMaintenanceSourcesButton.textContent = allSelected ? "清除" : "全选";
  elements.toggleAllSlimmingMaintenanceSourcesButton.disabled = submitting || sources.length === 0;

  for (const source of sources) {
    const row = document.createElement("label");
    row.className = "slimming-maintenance-source-option";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.checked = selected.has(source.id);
    input.disabled = submitting;
    input.dataset.slimmingMaintenanceSourceId = source.id;
    const name = document.createElement("strong");
    name.textContent = source.displayName;
    const kind = document.createElement("span");
    kind.textContent = `${source.kind === "photos" ? "照片图库" : "文件夹"} · ${slimmingSourceIndexShortStatus(source)}`;
    row.append(input, name, kind);
    elements.slimmingMaintenanceSourceOptions.append(row);
  }

  elements.refreshSlimmingSourcesButton.disabled = !state.online
    || submitting
    || selected.size === 0;
  elements.refreshSlimmingSourcesButton.lastElementChild.textContent =
    maintenance.submittingAction === "refreshCatalog"
      ? "正在交给 Mac…" : "刷新所选来源";

  const indexAvailable = snapshot.sourceSimilarityIndexAvailable === true;
  elements.slimmingSourceIndexSection.classList.toggle("hidden", !indexAvailable);
  clearElement(elements.slimmingIndexSourceSelect);
  for (const source of sources) {
    const option = document.createElement("option");
    option.value = source.id;
    option.textContent = source.displayName;
    elements.slimmingIndexSourceSelect.append(option);
  }
  if (!sources.some((source) => source.id === maintenance.indexSourceID)) {
    maintenance.indexSourceID = sources.find((source) => selected.has(source.id))?.id
      || sources[0]?.id
      || "";
  }
  elements.slimmingIndexSourceSelect.value = maintenance.indexSourceID;
  elements.slimmingIndexSourceSelect.disabled = submitting || sources.length === 0;
  const indexSource = sources.find((source) => source.id === maintenance.indexSourceID);
  const status = indexSource?.similarityIndex;
  elements.slimmingSourceIndexStatus.textContent = slimmingSourceIndexCaption(
    indexSource,
    indexAvailable
  );
  elements.slimmingSourceIndexStatus.classList.toggle("ready", status?.state === "ready");
  elements.slimmingSourceIndexStatus.classList.toggle(
    "warning",
    status?.state === "stale" || status?.state === "failed"
  );
  elements.initializeSlimmingSourceIndexButton.textContent =
    maintenance.submittingAction === "initializeSimilarityIndex"
      ? "正在交给 Mac…"
      : status?.state === "ready"
        ? "重新构建来源索引"
        : status?.state === "stale" || status?.state === "failed"
          ? "重新构建来源索引"
          : status?.state === "building"
            ? "正在构建来源索引…"
            : "初始化来源索引";
  elements.initializeSlimmingSourceIndexButton.disabled = !state.online
    || submitting
    || !indexSource
    || status?.state === "building";
  syncWriteActionControls();
}

function stopSlimmingSourceIndexPolling() {
  clearTimeout(state.slimming.sourceMaintenance.pollTimer);
  state.slimming.sourceMaintenance.pollTimer = null;
}

function scheduleSlimmingSourceIndexPolling() {
  stopSlimmingSourceIndexPolling();
  const maintenance = state.slimming.sourceMaintenance;
  const source = maintenance.snapshot?.sources?.find(
    (item) => item.id === maintenance.indexSourceID
  );
  if (source?.similarityIndex?.state !== "building"
    || elements.slimmingAnalysisOptionsPopover.classList.contains("hidden")) return;
  maintenance.pollTimer = setTimeout(() => {
    void loadSlimmingSourceMaintenance({ quiet: true });
  }, 1500);
}

async function loadSlimmingSourceMaintenance({ quiet = false } = {}) {
  const maintenance = state.slimming.sourceMaintenance;
  const generation = ++maintenance.requestGeneration;
  if (!quiet) maintenance.loading = true;
  maintenance.error = "";
  renderSlimmingSourceMaintenance();
  try {
    const query = new URLSearchParams({ mediaKind: state.slimming.mediaKind });
    const snapshot = await api(`/v1/library-slimming/setup?${query}`);
    if (generation !== maintenance.requestGeneration
      || elements.slimmingAnalysisOptionsPopover.classList.contains("hidden")) return;
    maintenance.snapshot = snapshot;
    setSlimmingCatalogSourceIDs(
      resolvedSlimmingCatalogSourceIDs(snapshot),
      snapshot
    );
  } catch (error) {
    if (generation === maintenance.requestGeneration) {
      maintenance.error = error.message || "来源维护状态载入失败";
    }
  } finally {
    if (generation === maintenance.requestGeneration) {
      maintenance.loading = false;
      renderSlimmingSourceMaintenance();
      scheduleSlimmingSourceIndexPolling();
    }
  }
}

function closeSlimmingAnalysisOptions({ restoreFocus = true } = {}) {
  const maintenance = state.slimming.sourceMaintenance;
  const wasOpen = !elements.slimmingAnalysisOptionsPopover.classList.contains("hidden");
  maintenance.requestGeneration += 1;
  maintenance.loading = false;
  stopSlimmingSourceIndexPolling();
  elements.slimmingAnalysisOptionsPopover.classList.add("hidden");
  elements.slimmingAnalysisOptionsButton.setAttribute("aria-expanded", "false");
  if (wasOpen && restoreFocus) restoreOverlayFocus(elements.slimmingAnalysisOptionsButton);
}

function openSlimmingAnalysisOptions() {
  elements.filterPopover.classList.add("hidden");
  closeJobsPopover({ restoreFocus: false });
  closePersonalModelPopover({ restoreFocus: false });
  elements.slimmingAnalysisOptionsPopover.classList.remove("hidden");
  elements.slimmingAnalysisOptionsButton.setAttribute("aria-expanded", "true");
  void loadSlimmingSourceMaintenance();
  requestAnimationFrame(() => {
    elements.closeSlimmingAnalysisOptionsButton.focus({ preventScroll: true });
  });
}

function toggleSlimmingAnalysisOptions() {
  if (elements.slimmingAnalysisOptionsPopover.classList.contains("hidden")) {
    openSlimmingAnalysisOptions();
  } else {
    closeSlimmingAnalysisOptions();
  }
}

async function submitSlimmingSourceMaintenance(action) {
  const maintenance = state.slimming.sourceMaintenance;
  if (!state.online || maintenance.submittingAction || !maintenance.snapshot) return;
  const sourceIDs = action === "refreshCatalog"
    ? [...maintenance.selectedSourceIDs]
    : [maintenance.indexSourceID].filter(Boolean);
  if (sourceIDs.length === 0 || (action === "initializeSimilarityIndex" && sourceIDs.length !== 1)) {
    maintenance.error = action === "refreshCatalog"
      ? "请至少选择一个要刷新的来源。"
      : "请选择一个要建立索引的来源。";
    renderSlimmingSourceMaintenance();
    return;
  }
  maintenance.submittingAction = action;
  maintenance.error = "";
  maintenance.operationID ||= crypto.randomUUID();
  renderSlimmingSourceMaintenance();
  try {
    const result = await api("/v1/library-slimming/source-maintenance", {
      method: "POST",
      body: JSON.stringify({
        operationID: maintenance.operationID,
        action,
        mediaKind: state.slimming.mediaKind,
        sourceIDs,
      }),
    });
    maintenance.snapshot = result.setup;
    maintenance.operationID = null;
    setSlimmingCatalogSourceIDs(
      action === "refreshCatalog"
        ? new Set(sourceIDs)
        : resolvedSlimmingCatalogSourceIDs(result.setup),
      result.setup
    );
    toast(action === "refreshCatalog"
      ? `已交给 Mac 刷新 ${sourceIDs.length} 个来源`
      : "来源索引已开始构建");
  } catch (error) {
    maintenance.error = error.message || (action === "refreshCatalog"
      ? "刷新来源失败"
      : "初始化来源索引失败");
  } finally {
    maintenance.submittingAction = null;
    renderSlimmingSourceMaintenance();
    scheduleSlimmingSourceIndexPolling();
  }
}

function syncSlimmingThresholdEditorControls() {
  const editor = state.slimming.thresholdEditor;
  const thresholds = editor.thresholds;
  if (!thresholds) return;
  elements.slimmingThresholdRecallMode.value = thresholds.featurePrintRecallMode;
  elements.slimmingThresholdRecallTopK.value = String(thresholds.featurePrintRecallTopK);
  elements.slimmingThresholdL2Mode.value = thresholds.featurePrintL2Mode;
  elements.slimmingThresholdL2Distance.value = String(
    thresholds.featurePrintMaxL2Distance
  );
  elements.slimmingThresholdDINOMode.value = thresholds.dinoCosineMode;
  elements.slimmingThresholdDINOSimilarity.value = String(
    thresholds.dinoCosineMinSimilarity
  );
  elements.slimmingThresholdBucketingMode.value = thresholds.sceneBucketingMode;
  elements.slimmingThresholdBucketActivationCount.value = String(
    thresholds.sceneBucketActivationAssetCount
  );
  const locked = editor.loading || editor.saving;
  for (const control of [
    elements.slimmingThresholdRecallMode,
    elements.slimmingThresholdL2Mode,
    elements.slimmingThresholdDINOMode,
    elements.slimmingThresholdBucketingMode,
  ]) control.disabled = locked;
  elements.slimmingThresholdRecallTopK.disabled = locked
    || thresholds.featurePrintRecallMode === "allCandidates";
  elements.slimmingThresholdL2Distance.disabled = locked
    || thresholds.featurePrintL2Mode === "unlimited";
  elements.slimmingThresholdDINOSimilarity.disabled = locked
    || thresholds.dinoCosineMode === "unlimited";
  elements.slimmingThresholdBucketActivationCount.disabled = locked
    || thresholds.sceneBucketingMode !== "automatic";
  elements.slimmingThresholdDialogExtremeWarning.classList.toggle(
    "hidden",
    thresholds.featurePrintRecallMode !== "allCandidates"
      && thresholds.featurePrintL2Mode !== "unlimited"
      && thresholds.dinoCosineMode !== "unlimited"
      && thresholds.sceneBucketingMode === "automatic"
  );
}

function renderSlimmingThresholdEditor() {
  const editor = state.slimming.thresholdEditor;
  elements.slimmingThresholdDialogLoading.classList.toggle("hidden", !editor.loading);
  elements.slimmingThresholdDialogContent.classList.toggle(
    "hidden",
    editor.loading || !editor.thresholds
  );
  elements.slimmingThresholdDialogError.textContent = editor.error;
  elements.applySlimmingThresholdDialogButton.textContent = editor.saving
    ? "正在保存…" : "应用";
  elements.resetSlimmingThresholdDialogButton.textContent = "恢复默认";
  syncSlimmingThresholdEditorControls();
  syncWriteActionControls();
}

function readSlimmingThresholdEditorControls() {
  const editor = state.slimming.thresholdEditor;
  editor.thresholds = {
    featurePrintRecallTopK: Number(elements.slimmingThresholdRecallTopK.value),
    featurePrintMaxL2Distance: Number(elements.slimmingThresholdL2Distance.value),
    dinoCosineMinSimilarity: Number(elements.slimmingThresholdDINOSimilarity.value),
    sceneBucketActivationAssetCount: Number(
      elements.slimmingThresholdBucketActivationCount.value
    ),
    featurePrintRecallMode: elements.slimmingThresholdRecallMode.value,
    featurePrintL2Mode: elements.slimmingThresholdL2Mode.value,
    dinoCosineMode: elements.slimmingThresholdDINOMode.value,
    sceneBucketingMode: elements.slimmingThresholdBucketingMode.value,
  };
  editor.operationID = null;
  editor.error = slimmingThresholdsValid(editor.thresholds)
    ? "" : "请检查相似阈值；数值必须在允许范围内。";
  renderSlimmingThresholdEditor();
}

async function openSlimmingThresholdEditor() {
  closeSlimmingAnalysisOptions({ restoreFocus: false });
  const editor = state.slimming.thresholdEditor;
  editor.loading = true;
  editor.saving = false;
  editor.thresholds = null;
  editor.factoryThresholds = null;
  editor.error = "";
  editor.operationID = null;
  const generation = ++editor.requestGeneration;
  elements.slimmingThresholdDialog.showModal();
  renderSlimmingThresholdEditor();
  requestAnimationFrame(() => {
    elements.closeSlimmingThresholdDialogButton.focus({ preventScroll: true });
  });
  try {
    const query = new URLSearchParams({ mediaKind: state.slimming.mediaKind });
    const snapshot = await api(`/v1/library-slimming/setup?${query}`);
    if (generation !== editor.requestGeneration || !elements.slimmingThresholdDialog.open) {
      return;
    }
    editor.thresholds = normalizeSlimmingThresholdDraft(snapshot.thresholds);
    editor.factoryThresholds = normalizeSlimmingThresholdDraft(snapshot.factoryThresholds);
  } catch (error) {
    if (generation === editor.requestGeneration) {
      editor.error = error.message || "相似阈值载入失败";
    }
  } finally {
    if (generation === editor.requestGeneration) {
      editor.loading = false;
      renderSlimmingThresholdEditor();
    }
  }
}

function closeSlimmingThresholdEditor({ restoreFocus = true } = {}) {
  const editor = state.slimming.thresholdEditor;
  editor.requestGeneration += 1;
  editor.loading = false;
  editor.saving = false;
  if (elements.slimmingThresholdDialog.open) elements.slimmingThresholdDialog.close();
  if (restoreFocus) restoreOverlayFocus(elements.slimmingAnalysisOptionsButton);
}

async function saveSlimmingThresholdEditor({ restoreFactory = false } = {}) {
  const editor = state.slimming.thresholdEditor;
  const nextThresholds = normalizeSlimmingThresholdDraft(
    restoreFactory ? editor.factoryThresholds : editor.thresholds
  );
  if (!state.online || editor.saving || !slimmingThresholdsValid(nextThresholds)) return;
  editor.thresholds = nextThresholds;
  editor.saving = true;
  editor.error = "";
  if (restoreFactory) editor.operationID = null;
  editor.operationID ||= crypto.randomUUID();
  renderSlimmingThresholdEditor();
  try {
    const result = await api("/v1/library-slimming/thresholds", {
      method: "PUT",
      body: JSON.stringify({
        operationID: editor.operationID,
        thresholds: editor.thresholds,
      }),
    });
    editor.thresholds = normalizeSlimmingThresholdDraft(result.thresholds);
    editor.operationID = null;
    state.slimming.setup.thresholds = normalizeSlimmingThresholdDraft(result.thresholds);
    if (state.slimming.setup.snapshot) {
      state.slimming.setup.snapshot.thresholds = result.thresholds;
    }
    toast(restoreFactory
      ? "已恢复默认阈值，将在下次分析生效"
      : "阈值已更新，将在下次分析生效");
  } catch (error) {
    editor.error = error.message || "相似阈值保存失败";
  } finally {
    editor.saving = false;
    renderSlimmingThresholdEditor();
  }
}

function canSaveSlimmingThresholds() {
  const setup = state.slimming.setup;
  return Boolean(setup.snapshot)
    && !setup.loading
    && !setup.saving
    && !setup.launching
    && slimmingThresholdsValid();
}

function canLaunchSlimmingSetup() {
  const setup = state.slimming.setup;
  if (!canSaveSlimmingThresholds() || !slimmingModeAvailable(setup.mode)) return false;
  if (setup.mode === "catalog") return setup.selectedSourceIDs.size > 0;
  if (setup.mode === "seeds") return currentSlimmingSeedIDs().length > 0;
  return state.mediaKind === state.slimming.mediaKind;
}

function appendSlimmingSetupSummary(label, value) {
  const term = document.createElement("dt");
  term.textContent = label;
  const description = document.createElement("dd");
  description.textContent = value;
  elements.slimmingLaunchSummary.append(term, description);
}

function renderSlimmingSetupModes() {
  clearElement(elements.slimmingModeOptions);
  for (const mode of ["catalog", "currentFilter", "seeds"]) {
    const copy = slimmingModeCopy(mode);
    const button = document.createElement("button");
    button.type = "button";
    button.className = "slimming-mode-option";
    button.classList.toggle("selected", state.slimming.setup.mode === mode);
    button.dataset.slimmingMode = mode;
    button.disabled = !slimmingModeAvailable(mode) || state.slimming.setup.launching;
    button.setAttribute("role", "radio");
    button.setAttribute("aria-checked", String(state.slimming.setup.mode === mode));
    const title = document.createElement("strong");
    title.textContent = copy.title;
    const detail = document.createElement("span");
    detail.textContent = copy.detail;
    button.append(title, detail);
    elements.slimmingModeOptions.append(button);
  }
}

function renderSlimmingSourceOptions() {
  const setup = state.slimming.setup;
  clearElement(elements.slimmingSourceOptions);
  elements.slimmingSourceSection.classList.toggle("hidden", setup.mode !== "catalog");
  if (setup.mode !== "catalog") return;
  const sources = setup.snapshot?.sources || [];
  const allSelected = sources.length > 0
    && sources.every((source) => setup.selectedSourceIDs.has(source.id));
  elements.toggleAllSlimmingSourcesButton.textContent = allSelected ? "清除" : "全选";
  elements.toggleAllSlimmingSourcesButton.disabled = setup.launching;
  elements.slimmingSourceHint.textContent = allSelected
    ? "已选择全部可用来源；提交时保留 Mac 端“全部来源”语义。"
    : `已选择 ${setup.selectedSourceIDs.size} / ${sources.length} 个来源。`;
  for (const source of sources) {
    const row = document.createElement("label");
    row.className = "training-option-row";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.checked = setup.selectedSourceIDs.has(source.id);
    input.disabled = setup.launching;
    input.dataset.slimmingSourceId = source.id;
    const name = document.createElement("strong");
    name.textContent = source.displayName;
    const kind = document.createElement("span");
    kind.textContent = source.kind === "photos" ? "照片图库" : "文件夹";
    row.append(input, name, kind);
    elements.slimmingSourceOptions.append(row);
  }
}

function syncSlimmingThresholdControls() {
  const setup = state.slimming.setup;
  const thresholds = setup.thresholds;
  if (!thresholds) return;
  elements.slimmingRecallMode.value = thresholds.featurePrintRecallMode;
  elements.slimmingRecallTopK.value = String(thresholds.featurePrintRecallTopK);
  elements.slimmingL2Mode.value = thresholds.featurePrintL2Mode;
  elements.slimmingL2Distance.value = String(thresholds.featurePrintMaxL2Distance);
  elements.slimmingDINOMode.value = thresholds.dinoCosineMode;
  elements.slimmingDINOSimilarity.value = String(thresholds.dinoCosineMinSimilarity);
  elements.slimmingBucketingMode.value = thresholds.sceneBucketingMode;
  elements.slimmingBucketActivationCount.value = String(
    thresholds.sceneBucketActivationAssetCount
  );
  const locked = setup.saving || setup.launching;
  elements.resetSlimmingThresholdsButton.disabled = locked;
  for (const control of [
    elements.slimmingRecallMode,
    elements.slimmingL2Mode,
    elements.slimmingDINOMode,
    elements.slimmingBucketingMode,
  ]) control.disabled = locked;
  elements.slimmingRecallTopK.disabled = locked
    || thresholds.featurePrintRecallMode === "allCandidates";
  elements.slimmingL2Distance.disabled = locked || thresholds.featurePrintL2Mode === "unlimited";
  elements.slimmingDINOSimilarity.disabled = locked || thresholds.dinoCosineMode === "unlimited";
  elements.slimmingBucketActivationCount.disabled = locked
    || thresholds.sceneBucketingMode !== "automatic";
  elements.slimmingExtremeWarning.classList.toggle(
    "hidden",
    thresholds.featurePrintRecallMode !== "allCandidates"
      && thresholds.featurePrintL2Mode !== "unlimited"
      && thresholds.dinoCosineMode !== "unlimited"
      && thresholds.sceneBucketingMode === "automatic"
  );
}

function renderSlimmingSetupSummary() {
  clearElement(elements.slimmingLaunchSummary);
  const setup = state.slimming.setup;
  const copy = slimmingModeCopy(setup.mode);
  appendSlimmingSetupSummary("范围", copy.title);
  if (setup.mode === "catalog") {
    const sourceCount = setup.snapshot?.sources?.length || 0;
    appendSlimmingSetupSummary(
      "来源",
      setup.selectedSourceIDs.size === sourceCount
        ? `全部 ${sourceCount} 个可用来源`
        : `${setup.selectedSourceIDs.size} 个来源`
    );
  } else if (setup.mode === "seeds") {
    appendSlimmingSetupSummary("种子", `${currentSlimmingSeedIDs().length} 项`);
  } else {
    appendSlimmingSetupSummary("筛选", state.searchText ? `包含搜索“${state.searchText}”` : "网页图库当前筛选");
  }
  appendSlimmingSetupSummary(
    "相似阈值",
    slimmingThresholdsValid() ? "使用面板中的共享设置" : "设置值无效"
  );
}

function renderSlimmingSetup() {
  const setup = state.slimming.setup;
  elements.slimmingSetupLoading.classList.toggle("hidden", !setup.loading);
  elements.slimmingSetupConfiguration.classList.toggle("hidden", setup.loading || !setup.snapshot);
  elements.slimmingSetupError.textContent = setup.error;
  elements.launchSlimmingButton.textContent = setup.launching ? "正在交给 Mac…" : "开始分析";
  elements.saveSlimmingThresholdsButton.textContent = setup.saving && !setup.launching
    ? "正在保存…"
    : "仅保存设置";
  if (setup.snapshot) {
    renderSlimmingSetupModes();
    renderSlimmingSourceOptions();
    syncSlimmingThresholdControls();
    renderSlimmingSetupSummary();
  }
  syncWriteActionControls();
}

async function openSlimmingSetupDialog() {
  closeSlimmingAnalysisOptions({ restoreFocus: false });
  const setup = state.slimming.setup;
  setup.loading = true;
  setup.saving = false;
  setup.launching = false;
  setup.snapshot = null;
  setup.error = "";
  setup.thresholdOperationID = null;
  setup.launchOperationID = null;
  const generation = ++setup.requestGeneration;
  elements.slimmingSetupDialog.showModal();
  renderSlimmingSetup();
  try {
    const query = new URLSearchParams({ mediaKind: state.slimming.mediaKind });
    const snapshot = await api(`/v1/library-slimming/setup?${query}`);
    if (generation !== setup.requestGeneration || !elements.slimmingSetupDialog.open) return;
    setup.snapshot = snapshot;
    setup.mode = slimmingModeAvailable("currentFilter") ? "currentFilter" : "catalog";
    setSlimmingCatalogSourceIDs(resolvedSlimmingCatalogSourceIDs(snapshot), snapshot);
    setup.thresholds = normalizeSlimmingThresholdDraft(snapshot.thresholds);
  } catch (error) {
    if (generation === setup.requestGeneration) {
      setup.error = error.message || "图库瘦身设置载入失败";
    }
  } finally {
    if (generation === setup.requestGeneration) {
      setup.loading = false;
      renderSlimmingSetup();
    }
  }
}

function closeSlimmingSetupDialog() {
  state.slimming.setup.requestGeneration += 1;
  state.slimming.setup.saving = false;
  state.slimming.setup.launching = false;
  if (elements.slimmingSetupDialog.open) elements.slimmingSetupDialog.close();
  restoreOverlayFocus(elements.newSlimmingAnalysisButton);
}

function readSlimmingThresholdControls() {
  const setup = state.slimming.setup;
  setup.thresholds = {
    featurePrintRecallTopK: Number(elements.slimmingRecallTopK.value),
    featurePrintMaxL2Distance: Number(elements.slimmingL2Distance.value),
    dinoCosineMinSimilarity: Number(elements.slimmingDINOSimilarity.value),
    sceneBucketActivationAssetCount: Number(elements.slimmingBucketActivationCount.value),
    featurePrintRecallMode: elements.slimmingRecallMode.value,
    featurePrintL2Mode: elements.slimmingL2Mode.value,
    dinoCosineMode: elements.slimmingDINOMode.value,
    sceneBucketingMode: elements.slimmingBucketingMode.value,
  };
  setup.thresholdOperationID = null;
  setup.error = slimmingThresholdsValid() ? "" : "请检查相似阈值；数值必须在允许范围内。";
  renderSlimmingSetup();
}

async function saveSlimmingThresholds({ forLaunch = false } = {}) {
  const setup = state.slimming.setup;
  if (!slimmingThresholdsValid() || setup.saving) return false;
  setup.saving = true;
  setup.error = "";
  setup.thresholdOperationID ||= crypto.randomUUID();
  renderSlimmingSetup();
  try {
    const result = await api("/v1/library-slimming/thresholds", {
      method: "PUT",
      body: JSON.stringify({
        operationID: setup.thresholdOperationID,
        thresholds: setup.thresholds,
      }),
    });
    setup.thresholds = normalizeSlimmingThresholdDraft(result.thresholds);
    if (setup.snapshot) setup.snapshot.thresholds = result.thresholds;
    setup.thresholdOperationID = null;
    if (!forLaunch) toast("相似阈值已保存到 Mac");
    return true;
  } catch (error) {
    setup.error = error.message || "相似阈值保存失败";
    return false;
  } finally {
    setup.saving = false;
    renderSlimmingSetup();
  }
}

async function submitSlimmingSetup() {
  const setup = state.slimming.setup;
  if (!canLaunchSlimmingSetup()) return;
  setup.launching = true;
  setup.error = "";
  renderSlimmingSetup();
  if (!await saveSlimmingThresholds({ forLaunch: true })) {
    setup.launching = false;
    renderSlimmingSetup();
    return;
  }
  setup.launchOperationID ||= crypto.randomUUID();
  const allSourceIDs = (setup.snapshot?.sources || []).map((source) => source.id);
  const selectedSourceIDs = [...setup.selectedSourceIDs];
  const allSourcesSelected = allSourceIDs.length === selectedSourceIDs.length
    && allSourceIDs.every((id) => setup.selectedSourceIDs.has(id));
  try {
    const result = await api("/v1/library-slimming/launch", {
      method: "POST",
      body: JSON.stringify({
        operationID: setup.launchOperationID,
        mediaKind: state.slimming.mediaKind,
        mode: setup.mode,
        sourceIDs: setup.mode === "catalog"
          ? (allSourcesSelected ? null : selectedSourceIDs)
          : null,
        seedAssetIDs: setup.mode === "seeds" ? currentSlimmingSeedIDs() : [],
        filter: setup.mode === "catalog" ? null : currentSlimmingFilterRequest(),
      }),
    });
    closeSlimmingSetupDialog();
    state.slimming.selectedJobID = result.jobID;
    toast(`分析已交给 Mac · ${result.memberCount} 项`);
    await loadSlimmingWorkspace({ jobID: result.jobID, quiet: true });
  } catch (error) {
    setup.error = error.message || "图库瘦身分析创建失败";
    setup.launching = false;
    renderSlimmingSetup();
  }
}

async function applySlimmingJobAction(
  jobID,
  action,
  { returnFocus = false, confirmed = false } = {}
) {
  if (!state.online || state.slimming.jobMutatingIDs.has(jobID)) return;
  if (action === "deleteRecord" && !confirmed) {
    requestConfirmation({
      eyebrow: "ANALYSIS RECORD",
      title: "删除这条分析记录？",
      message: "只会永久删除分析任务记录和结果；不会读取、移动或删除任何原始媒体。",
      actionLabel: "删除记录",
      tone: "danger",
      returnFocus: { slimmingJobID: jobID },
      action: () => applySlimmingJobAction(jobID, action, {
        returnFocus,
        confirmed: true,
      }),
    });
    return;
  }
  const selectedBefore = state.slimming.selectedJobID;
  state.slimming.jobMutatingIDs.add(jobID);
  renderSlimmingJobs();
  try {
    await api(`/v1/library-slimming/jobs/${jobID}/actions`, {
      method: "POST",
      body: JSON.stringify({ operationID: crypto.randomUUID(), action }),
    });
    toast({ pause: "分析已暂停", resume: "分析已继续", deleteRecord: "分析记录已删除" }[action]);
    if (action === "deleteRecord" && selectedBefore === jobID) {
      state.slimming.selectedJobID = null;
      state.slimming.selectedClusterID = null;
      state.slimming.selectedMemberIDs.clear();
      state.slimming.selectionAnchorID = null;
    } else if (action === "deleteRecord") {
      state.slimming.selectedJobID = selectedBefore;
    }
    await loadSlimmingWorkspace({ quiet: true });
    if (returnFocus || action === "deleteRecord") focusSelectedSlimmingJob();
  } catch (error) {
    toast(error.message || "分析任务操作失败");
    if (returnFocus) {
      restoreOverlayFocus(elements.slimmingJobList.querySelector(
        `[data-slimming-job-id="${CSS.escape(jobID)}"]`
      ));
    }
  } finally {
    state.slimming.jobMutatingIDs.delete(jobID);
    renderSlimmingJobs();
  }
}

async function applyReviewDecision(action) {
  const selectedItems = selectedReviewItems();
  const assetIDs = selectedItems.map((item) => item.assetID);
  const tagID = elements.reviewTagSelect.value;
  const generation = state.workspaceGeneration;
  if (!state.online
    || !assetIDs.length
    || !tagID
    || state.review.loading
    || state.review.mutating
    || state.review.loadedScopeKey !== currentReviewScopeKey()) return;
  state.review.mutating = true;
  syncReviewControls();
  try {
    const result = await api("/v1/review/decisions/batch", {
      method: "POST",
      body: JSON.stringify({
        operationID: crypto.randomUUID(),
        tagID,
        assetIDs,
        action,
      }),
    });
    if (generation !== state.workspaceGeneration) return;
    const previousIndex = state.review.selectedIndex;
    try {
      await Promise.all([
        loadReviewOverview({ throwOnError: true }),
        loadReviewQueue({
          preserveLoadedWindow: true,
          throwOnError: true,
        }),
        loadAssets({
          preserveSelection: true,
          preserveUnchangedGrid: true,
          preserveLoadedWindow: true,
        }),
      ]);
      if (generation !== state.workspaceGeneration) return;
      if (state.review.items.length) {
        selectReviewIndex(Math.min(previousIndex, state.review.items.length - 1));
      }
      undoToast(
        result.replayed
          ? "审核操作已恢复"
          : `已为 ${mediaItemCountText(result.appliedAssetCount)}保存审核决定`,
        result.undoID,
        "review"
      );
    } catch {
      if (generation === state.workspaceGeneration) {
        void refreshWorkspace({
          quiet: true,
          kinds: ["reviewChanged", "assetsChanged"],
        });
        undoToast(
          "审核决定已保存，界面同步暂时失败，正在重试",
          result.undoID,
          "review"
        );
      }
    }
  } catch (error) {
    if (generation === state.workspaceGeneration) {
      toast(error.message || "审核决定保存失败");
    }
  } finally {
    if (generation === state.workspaceGeneration) {
      state.review.mutating = false;
      syncReviewControls();
    }
  }
}

function deferReviewSelection() {
  const selectedIDs = new Set(state.review.selectedAssetIDs);
  if (state.review.loading
    || state.review.mutating
    || state.review.loadedScopeKey !== currentReviewScopeKey()
    || !selectedIDs.size
    || !state.review.items.length) return;
  const selectedIndexes = state.review.items
    .map((item, index) => selectedIDs.has(item.assetID) ? index : -1)
    .filter((index) => index >= 0);
  const lastSelectedIndex = selectedIndexes.length ? Math.max(...selectedIndexes) : -1;
  let nextIndex = state.review.items.findIndex((item, index) => (
    index > lastSelectedIndex && !selectedIDs.has(item.assetID)
  ));
  if (nextIndex < 0) {
    nextIndex = state.review.items.findIndex((item) => !selectedIDs.has(item.assetID));
  }
  if (nextIndex < 0) nextIndex = 0;
  selectReviewIndex(nextIndex);
  reviewCardMainButton(
    elements.reviewGrid.querySelector(`[data-review-index="${nextIndex}"]`)
  )?.focus({ preventScroll: true });
  toast(selectedIDs.size > 1
    ? `已跳过 ${mediaItemCountText(selectedIDs.size)}，没有修改标签决定`
    : "已跳到下一项，没有修改标签决定");
}

function lightboxItems() {
  if (state.lightboxContext === "review") {
    return state.review.items.map((item) => ({
      id: item.assetID,
      fileName: item.fileName,
      contentRevision: item.contentRevision,
    }));
  }
  if (state.lightboxContext === "slimming") {
    return state.slimming.members;
  }
  if (state.lightboxContext === "worldMap") {
    return state.worldMap.selection?.assets || [];
  }
  return state.assets;
}

function lightboxViewportMetrics(overrides = null) {
  if (overrides) return overrides;
  const viewport = elements.lightboxStage.getBoundingClientRect();
  const naturalWidth = elements.lightboxImage.naturalWidth
    || Number(elements.lightboxImage.dataset.width || 0);
  const naturalHeight = elements.lightboxImage.naturalHeight
    || Number(elements.lightboxImage.dataset.height || 0);
  if (viewport.width <= 0 || viewport.height <= 0
    || naturalWidth <= 0 || naturalHeight <= 0) {
    return {
      viewportWidth: Math.max(0, viewport.width),
      viewportHeight: Math.max(0, viewport.height),
      fittedWidth: 0,
      fittedHeight: 0,
    };
  }
  const fitScale = Math.min(viewport.width / naturalWidth, viewport.height / naturalHeight);
  return {
    viewportWidth: viewport.width,
    viewportHeight: viewport.height,
    fittedWidth: naturalWidth * fitScale,
    fittedHeight: naturalHeight * fitScale,
  };
}

function constrainedLightboxOffset(x, y, scale, metrics = lightboxViewportMetrics()) {
  const limitX = Math.max(0, (metrics.fittedWidth * scale - metrics.viewportWidth) / 2);
  const limitY = Math.max(0, (metrics.fittedHeight * scale - metrics.viewportHeight) / 2);
  return {
    x: Math.min(limitX, Math.max(-limitX, Number(x) || 0)),
    y: Math.min(limitY, Math.max(-limitY, Number(y) || 0)),
  };
}

function syncLightboxViewport() {
  const imageMode = Boolean(state.lightboxContext && lightboxMediaKind() !== "video");
  elements.lightboxZoomControls.classList.toggle("hidden", !imageMode);
  if (!imageMode) {
    elements.lightboxImage.style.removeProperty("transform");
    elements.lightboxImage.style.removeProperty("cursor");
    elements.lightboxZoomPercentage.textContent = "100%";
    elements.lightbox.dataset.zoomed = "false";
    elements.lightbox.setAttribute(
      "aria-label",
      state.lightboxContext && lightboxMediaKind() === "video"
        ? "视频全屏预览"
        : "照片全屏预览"
    );
    return;
  }
  const scale = Math.min(
    LIGHTBOX_MAX_SCALE,
    Math.max(LIGHTBOX_MIN_SCALE, Number(state.lightboxViewportScale) || 1)
  );
  const offset = scale <= LIGHTBOX_MIN_SCALE
    ? { x: 0, y: 0 }
    : constrainedLightboxOffset(
      state.lightboxViewportOffsetX,
      state.lightboxViewportOffsetY,
      scale
    );
  state.lightboxViewportScale = scale;
  state.lightboxViewportOffsetX = offset.x;
  state.lightboxViewportOffsetY = offset.y;
  const percentage = Math.round(scale * 100);
  elements.lightboxImage.style.transform = `translate3d(${offset.x}px, ${offset.y}px, 0) scale(${scale})`;
  elements.lightboxImage.style.cursor = scale > 1
    ? (state.lightboxViewportPointerID == null ? "grab" : "grabbing")
    : "zoom-in";
  elements.lightboxZoomPercentage.textContent = `${percentage}%`;
  elements.lightboxZoomResetButton.setAttribute(
    "aria-label",
    scale > 1 ? `当前缩放 ${percentage}%，恢复适应大小` : "当前为适应大小"
  );
  elements.lightboxZoomOutButton.disabled = scale <= LIGHTBOX_MIN_SCALE;
  elements.lightboxZoomInButton.disabled = scale >= LIGHTBOX_MAX_SCALE;
  elements.lightbox.dataset.zoomed = String(scale > 1);
  elements.lightbox.setAttribute(
    "aria-label",
    `照片全屏预览，当前缩放 ${percentage}%`
  );
}

function resetLightboxViewport(assetID = state.lightboxAssetID) {
  state.lightboxViewportAssetID = assetID || null;
  state.lightboxViewportScale = LIGHTBOX_MIN_SCALE;
  state.lightboxViewportOffsetX = 0;
  state.lightboxViewportOffsetY = 0;
  state.lightboxViewportPointerID = null;
  elements.lightboxStage.classList.remove("dragging");
  syncLightboxViewport();
}

function setLightboxScale(nextScale) {
  if (lightboxMediaKind() === "video") return;
  state.lightboxViewportScale = Math.min(
    LIGHTBOX_MAX_SCALE,
    Math.max(LIGHTBOX_MIN_SCALE, Number(nextScale) || LIGHTBOX_MIN_SCALE)
  );
  if (state.lightboxViewportScale <= LIGHTBOX_MIN_SCALE) {
    state.lightboxViewportOffsetX = 0;
    state.lightboxViewportOffsetY = 0;
  }
  syncLightboxViewport();
}

function zoomLightboxBy(factor) {
  setLightboxScale(state.lightboxViewportScale * factor);
}

function handleLightboxWheel(event) {
  if (lightboxMediaKind() === "video") return;
  event.preventDefault();
  const limitedDelta = Math.min(500, Math.max(-500, event.deltaY));
  const sensitivity = event.deltaMode === WheelEvent.DOM_DELTA_PIXEL ? 0.002 : 0.08;
  setLightboxScale(state.lightboxViewportScale * Math.exp(-limitedDelta * sensitivity));
}

function beginLightboxPan(event) {
  if (lightboxMediaKind() === "video" || state.lightboxViewportScale <= 1
    || event.button !== 0 || state.lightboxViewportPointerID != null) return;
  event.preventDefault();
  state.lightboxViewportPointerID = event.pointerId;
  state.lightboxViewportDragStartX = event.clientX;
  state.lightboxViewportDragStartY = event.clientY;
  state.lightboxViewportDragOriginX = state.lightboxViewportOffsetX;
  state.lightboxViewportDragOriginY = state.lightboxViewportOffsetY;
  elements.lightboxStage.setPointerCapture?.(event.pointerId);
  elements.lightboxStage.classList.add("dragging");
  syncLightboxViewport();
}

function moveLightboxPan(event) {
  if (event.pointerId !== state.lightboxViewportPointerID) return;
  event.preventDefault();
  const offset = constrainedLightboxOffset(
    state.lightboxViewportDragOriginX + event.clientX - state.lightboxViewportDragStartX,
    state.lightboxViewportDragOriginY + event.clientY - state.lightboxViewportDragStartY,
    state.lightboxViewportScale
  );
  state.lightboxViewportOffsetX = offset.x;
  state.lightboxViewportOffsetY = offset.y;
  syncLightboxViewport();
}

function endLightboxPan(event) {
  if (event.pointerId !== state.lightboxViewportPointerID) return;
  state.lightboxViewportPointerID = null;
  if (elements.lightboxStage.hasPointerCapture?.(event.pointerId)) {
    elements.lightboxStage.releasePointerCapture(event.pointerId);
  }
  elements.lightboxStage.classList.remove("dragging");
  syncLightboxViewport();
}

function lightboxMediaKind() {
  if (state.lightboxContext === "slimming") return state.slimming.mediaKind;
  if (state.lightboxContext === "worldMap") return "image";
  return state.mediaKind;
}

function lightboxHasMoreItems() {
  if (state.lightboxContext === "library") return Boolean(state.nextCursor);
  if (state.lightboxContext === "review") return Boolean(state.review.nextCursor);
  return false;
}

function lightboxBackText() {
  return {
    library: "返回网格",
    review: "返回审核",
    slimming: "返回分析",
    worldMap: "返回地图",
  }[state.lightboxContext] || "返回";
}

async function renderLightboxMedia(item) {
  const mediaKind = lightboxMediaKind();
  if (mediaKind !== "video") {
    stopLightboxVideo();
    elements.lightboxImage.classList.remove("hidden");
    if (item.width) elements.lightboxImage.dataset.width = String(item.width);
    else delete elements.lightboxImage.dataset.width;
    if (item.height) elements.lightboxImage.dataset.height = String(item.height);
    else delete elements.lightboxImage.dataset.height;
    const revision = item.contentRevision == null ? "" : `?r=${item.contentRevision}`;
    setProtectedImageSource(elements.lightboxImage, `/v1/assets/${item.id}/preview${revision}`);
    syncLightboxViewport();
    return;
  }

  const requestGeneration = ++state.lightboxRequestGeneration;
  clearProtectedImageSource(elements.lightboxImage);
  elements.lightboxImage.classList.add("hidden");
  elements.lightboxVideo.pause();
  elements.lightboxVideo.removeAttribute("src");
  const poster = assetThumbnailPlaceholder(item.id);
  if (poster) elements.lightboxVideo.poster = poster;
  else elements.lightboxVideo.removeAttribute("poster");
  elements.lightboxVideo.dataset.assetId = item.id;
  elements.lightboxVideo.dataset.contentRevision = String(item.contentRevision ?? "");
  if (state.authMode === "account") {
    const workerReady = await updateMediaWorkerAuthorization(state.accountAuthorization);
    if (!workerReady
      || requestGeneration !== state.lightboxRequestGeneration
      || state.lightboxAssetID !== item.id) {
      if (requestGeneration === state.lightboxRequestGeneration
        && state.lightboxAssetID === item.id) {
        toast("当前浏览器无法建立视频播放通道");
      }
      return;
    }
  }
  if (requestGeneration !== state.lightboxRequestGeneration
    || state.lightboxAssetID !== item.id) return;
  const revision = item.contentRevision == null ? "" : `?r=${item.contentRevision}`;
  elements.lightboxVideo.src = `/v1/assets/${item.id}/media${revision}`;
  elements.lightboxVideo.classList.remove("hidden");
  elements.lightboxVideo.load();
}

function openLightbox(context, assetID) {
  if (!assetID) return;
  stopAssetHoverVideo();
  if (elements.lightbox.classList.contains("hidden")) {
    state.lightboxReturnFocus = document.activeElement;
  }
  state.lightboxContext = context;
  state.lightboxAssetID = assetID;
  if (context === "review") {
    elements.reviewWorkspace.inert = true;
  } else if (context === "slimming") {
    elements.slimmingWorkspace.inert = true;
  } else if (context === "worldMap") {
    elements.worldMapWorkspace.inert = true;
  }
  elements.lightbox.classList.remove("hidden");
  if (context === "library") syncLightboxWorkspaceFrame();
  renderLightbox();
  requestAnimationFrame(() => {
    elements.lightboxBackButton.focus({ preventScroll: true });
  });
}

function syncLightboxOpenOriginalControl(item) {
  const isVideo = lightboxMediaKind() === "video";
  elements.lightboxOpenOriginalButton.classList.toggle("hidden", !isVideo);
  if (!isVideo) return;
  const fileName = item?.fileName || "当前视频";
  const label = state.openingOriginal ? "正在打开…" : "Mac 播放";
  const description = state.openingOriginal
    ? `正在 Mac 上打开${fileName}`
    : `在 Mac 上用系统播放器打开${fileName}`;
  elements.lightboxOpenOriginalButtonLabel.textContent = label;
  elements.lightboxOpenOriginalButton.disabled = !state.online
    || item?.availability !== "available"
    || state.openingOriginal
    || state.lightboxNavigating;
  elements.lightboxOpenOriginalButton.classList.toggle("busy", state.openingOriginal);
  elements.lightboxOpenOriginalButton.title = description;
  elements.lightboxOpenOriginalButton.setAttribute("aria-label", description);
}

function renderLightbox() {
  const items = lightboxItems();
  const index = items.findIndex((item) => item.id === state.lightboxAssetID);
  if (index < 0) {
    closeLightbox();
    return;
  }
  const item = items[index];
  if (state.lightboxViewportAssetID !== item.id) resetLightboxViewport(item.id);
  const noun = lightboxMediaKind() === "video" ? "视频" : "照片";
  const hasMore = lightboxHasMoreItems();
  elements.lightboxTitle.textContent = item.fileName || `未命名${noun}`;
  elements.lightboxImage.alt = item.fileName || `${noun}全屏预览`;
  void renderLightboxMedia(item);
  elements.lightboxBackLabel.textContent = lightboxBackText();
  elements.lightboxBackButton.setAttribute("aria-label", lightboxBackText());
  elements.lightboxPosition.textContent = `${index + 1} / ${items.length}${hasMore ? " · 还有更多" : ""}`;
  elements.lightboxPreviousButton.disabled = state.lightboxNavigating || index <= 0;
  elements.lightboxNextButton.disabled = state.lightboxNavigating
    || (index >= items.length - 1 && !hasMore);
  elements.lightbox.setAttribute("aria-busy", String(state.lightboxNavigating));
  elements.lightboxReviewActions.classList.toggle(
    "hidden",
    state.lightboxContext !== "review"
  );
  elements.lightbox.classList.toggle("reviewing", state.lightboxContext === "review");
  const showsDelete = state.lightboxContext === "slimming";
  elements.lightboxDeleteButton.classList.toggle("hidden", !showsDelete);
  elements.lightboxDeleteButton.disabled = !state.online
    || state.lightboxNavigating
    || state.slimming.removal.submitting
    || Boolean(activeSlimmingRemovalPhase(item.id));
  elements.lightboxDeleteButton.setAttribute(
    "aria-label",
    `处理当前预览${noun}：${item.fileName || `未命名${noun}`}`
  );
  syncLightboxOpenOriginalControl(item);
  renderLightboxFavorite();
  if (!favoriteStateForAssetID(item.id)) void loadLightboxFavorite(item.id);
  syncReviewControls();
}

function syncReviewLightboxSelection() {
  if (state.lightboxContext !== "review") return;
  const item = state.review.items[state.review.selectedIndex];
  if (!item) {
    closeLightbox();
    return;
  }
  state.lightboxAssetID = item.assetID;
  renderLightbox();
}

async function applyLightboxReviewDecision(action) {
  if (state.lightboxContext !== "review") return;
  const currentIndex = state.review.items.findIndex(
    (item) => item.assetID === state.lightboxAssetID
  );
  if (currentIndex >= 0 && currentIndex !== state.review.selectedIndex) {
    selectReviewIndex(currentIndex);
  }
  if (action === "defer") {
    deferReviewSelection();
    syncReviewLightboxSelection();
    return;
  }
  await applyReviewDecision(action);
  syncReviewLightboxSelection();
}

async function loadMoreLightboxItems() {
  if (state.lightboxContext === "library" && state.nextCursor) {
    await loadAssets({ append: true, preserveSelection: true });
    return;
  }
  if (state.lightboxContext === "review" && state.review.nextCursor) {
    await loadReviewQueue({ append: true, preserveUnchangedGrid: true });
  }
}

async function syncLibraryLightboxSelection(assetID) {
  state.selectedAssetID = assetID;
  state.selectedDetail = null;
  if (state.selectionMode) {
    state.selectedAssetIDs = new Set([assetID]);
    state.selectionAnchorID = assetID;
  }
  renderAssets();
  renderSelectionBar();
  const card = elements.assetGrid.querySelector(`[data-asset-id="${CSS.escape(assetID)}"]`);
  card?.scrollIntoView({ block: "nearest", inline: "nearest" });
  if (card) state.lightboxReturnFocus = assetCardMainButton(card);
  if (state.selectionMode) {
    scheduleSelectionAggregate();
    return;
  }
  await loadInspector(assetID, { preserveExisting: false, quiet: true });
}

async function navigateLightbox(direction) {
  if (![-1, 1].includes(direction)) return;
  if (state.lightboxNavigating) {
    state.lightboxPendingDirection = direction;
    return;
  }
  const currentAssetID = state.lightboxAssetID;
  let items = lightboxItems();
  let index = items.findIndex((item) => item.id === currentAssetID);
  if (index < 0) return;
  let next = index + direction;
  state.lightboxNavigating = true;
  renderLightbox();
  try {
    if (direction > 0 && next >= items.length && lightboxHasMoreItems()) {
      await loadMoreLightboxItems();
      if (state.lightboxAssetID !== currentAssetID) return;
      items = lightboxItems();
      index = items.findIndex((item) => item.id === currentAssetID);
      next = index + direction;
    }
    if (next < 0 || next >= items.length) return;
    const nextAssetID = items[next].id;
    state.lightboxAssetID = nextAssetID;
    renderLightbox();
    if (state.lightboxContext === "review") {
      selectReviewIndex(next);
    } else if (state.lightboxContext === "library") {
      await syncLibraryLightboxSelection(nextAssetID);
    }
  } catch (error) {
    toast(error.message || "无法载入下一页");
  } finally {
    state.lightboxNavigating = false;
    const pendingDirection = state.lightboxPendingDirection;
    state.lightboxPendingDirection = 0;
    if (!elements.lightbox.classList.contains("hidden") && state.lightboxAssetID) {
      renderLightbox();
      if (pendingDirection) void navigateLightbox(pendingDirection);
    }
  }
}

function navigateLibrarySelection(direction) {
  const index = state.assets.findIndex((asset) => asset.id === state.selectedAssetID);
  const next = index + direction;
  if (index < 0 || next < 0 || next >= state.assets.length) return;
  selectLibraryAssetByIndex(next);
}

function renderedGridColumnCount(container, cardSelector) {
  const cards = [...container.querySelectorAll(cardSelector)];
  if (!cards.length) return 1;
  const firstTop = cards[0].offsetTop;
  const count = cards.findIndex((card) => Math.abs(card.offsetTop - firstTop) > 1);
  return count < 0 ? cards.length : Math.max(1, count);
}

function renderedGridPageItemCount(scrollContainer, grid, cardSelector) {
  const columns = renderedGridColumnCount(grid, cardSelector);
  const card = grid.querySelector(cardSelector);
  if (!card) return columns;
  const rowGap = Number.parseFloat(getComputedStyle(grid).rowGap) || 0;
  const rowHeight = Math.max(1, card.getBoundingClientRect().height + rowGap);
  const rows = Math.max(1, Math.floor(scrollContainer.clientHeight / rowHeight));
  return rows * columns;
}

function gridColumnCount() {
  return renderedGridColumnCount(elements.assetGrid, ":scope > .asset-card");
}

function visibleGridPageItemCount() {
  return renderedGridPageItemCount(
    elements.libraryScroll,
    elements.assetGrid,
    ":scope > .asset-card"
  );
}

async function selectLibraryAssetByIndex(
  index,
  { focusGrid = false, extendRange = false } = {}
) {
  if (!state.assets.length) return;
  const bounded = Math.max(0, Math.min(index, state.assets.length - 1));
  const assetID = state.assets[bounded].id;
  if (state.selectionMode) {
    if (extendRange) {
      const candidateAnchorID = state.selectionAnchorID || state.selectedAssetID;
      const candidateAnchorIndex = state.assets.findIndex(
        (asset) => asset.id === candidateAnchorID
      );
      const anchorIndex = candidateAnchorIndex >= 0 ? candidateAnchorIndex : bounded;
      const anchorID = state.assets[anchorIndex].id;
      const next = new Set();
      for (
        let candidate = Math.min(anchorIndex, bounded);
        candidate <= Math.max(anchorIndex, bounded);
        candidate += 1
      ) {
        next.add(state.assets[candidate].id);
      }
      state.selectedAssetIDs = next;
      state.selectionAnchorID = anchorID;
    } else {
      state.selectedAssetIDs = new Set([assetID]);
      state.selectionAnchorID = assetID;
    }
    state.selectedAssetID = assetID;
    renderAssets();
    renderSelectionBar();
    scheduleSelectionAggregate();
  } else {
    state.selectedAssetID = assetID;
    state.selectedDetail = null;
    renderAssets();
    renderInspectorSurface();
  }
  const card = elements.assetGrid.querySelector(`[data-asset-id="${assetID}"]`);
  card?.scrollIntoView({ block: "nearest", inline: "nearest" });
  if (focusGrid) assetCardMainButton(card)?.focus({ preventScroll: true });
  if (!state.selectionMode) {
    await loadInspector(assetID, {
      reveal: true,
      focusInspector: !focusGrid,
    });
  }
}

function moveLibrarySelection(key, { extendRange = false } = {}) {
  if (!state.assets.length) return;
  const primaryID = state.selectionMode
    ? (
      state.selectedAssetID && state.selectedAssetIDs.has(state.selectedAssetID)
        ? state.selectedAssetID
        : (state.selectionAnchorID || [...state.selectedAssetIDs][0])
    )
    : state.selectedAssetID;
  const index = state.assets.findIndex((asset) => asset.id === primaryID);
  if (index < 0) {
    selectLibraryAssetByIndex(0, { focusGrid: true });
    return;
  }
  let nextIndex;
  if (key === "Home") {
    nextIndex = 0;
  } else if (key === "End") {
    nextIndex = state.assets.length - 1;
  } else {
    const columns = gridColumnCount();
    const delta = {
      ArrowLeft: -1,
      ArrowRight: 1,
      ArrowUp: -columns,
      ArrowDown: columns,
      PageUp: -visibleGridPageItemCount(),
      PageDown: visibleGridPageItemCount(),
    }[key];
    if (!delta) return;
    nextIndex = index + delta;
  }
  selectLibraryAssetByIndex(nextIndex, { focusGrid: true, extendRange });
}

async function loadWorkspace() {
  resetWorkspaceSessionState();
  const generation = state.workspaceGeneration;
  showApp();
  setConnection(true, "正在同步");
  const capabilities = await api("/v1/capabilities");
  if (generation !== state.workspaceGeneration) return;
  state.capabilities = capabilities;
  const [
    sources,
    tags,
    tagGroups,
    jobs,
    sourceManagement,
    embeddingPreparation,
    sampleSuggestions,
    tagLibrarySuggestions,
    librarySuggestions,
    workspaceNotice,
  ] = await Promise.all([
    api("/v1/sources"),
    api("/v1/tags"),
    api("/v1/tag-groups"),
    api("/v1/jobs"),
    supportsSourceManagement() ? api("/v1/source-management") : Promise.resolve(null),
    api(`/v1/embedding-preparation?${new URLSearchParams({ mediaKind: state.mediaKind })}`),
    api(`/v1/sample-suggestions?${new URLSearchParams({ mediaKind: state.mediaKind })}`),
    api(`/v1/tag-library-suggestions?${new URLSearchParams({ mediaKind: state.mediaKind })}`),
    supportsLibrarySuggestions()
      ? api(`/v1/library-suggestions?${new URLSearchParams({ mediaKind: state.mediaKind })}`)
      : Promise.resolve(null),
    supportsWorkspaceNotices()
      ? api("/v1/workspace-notice").catch(() => null)
      : Promise.resolve(null),
  ]);
  if (generation !== state.workspaceGeneration) return;
  state.sources = sources;
  state.tags = tags;
  state.tagGroups = tagGroups;
  state.jobs = jobs;
  state.sourceManagement.snapshot = sourceManagement || {
    sources,
    canConnectPhotos: !sources.some((source) => source.kind === "photos"),
    requests: [],
  };
  state.embeddingPreparation.isAvailable = Boolean(embeddingPreparation.isAvailable);
  state.embeddingPreparation.activities = embeddingPreparation.activities || [];
  state.sampleSuggestions.isAvailable = Boolean(sampleSuggestions.isAvailable);
  state.sampleSuggestions.maximumSampleCount = sampleSuggestions.maximumSampleCount || 500;
  state.sampleSuggestions.activities = sampleSuggestions.activities || [];
  state.tagLibrarySuggestions.snapshot = tagLibrarySuggestions;
  state.librarySuggestions.snapshot = librarySuggestions;
  state.workspaceNotice.notice = workspaceNotice?.notice || null;
  state.workspaceNotice.dismissing = false;
  state.workspaceNotice.activeActionID = null;
  renderWorkspaceNotice();
  elements.hostVersion.textContent = `Mac Host ${capabilities.hostAppVersion}`;
  elements.settingsButton.disabled = !supportsGeneralSettings();
  elements.settingsButton.title = supportsGeneralSettings()
    ? "设置（⌘,）"
    : "当前 Mac Host 不支持网页通用设置";
  if (supportsGeneralSettings()) await loadGeneralSettings({ quiet: true });
  if (generation !== state.workspaceGeneration) return;
  renderSources();
  renderReviewSourceFilter();
  renderTagSelects();
  renderJobs();
  renderSourcePrewarmStatus();
  renderMediaKindTabs();
  syncSelectionModeControls();
  renderLayoutPreferences();
  syncFilterControlsFromState();
  updateLibraryTitle();
  await loadAssets();
  if (generation !== state.workspaceGeneration) return;
  if (supportsLibrarySlimming()) {
    await loadSlimmingIdenticalCleanupRequests({ quiet: true });
  }
  if (generation !== state.workspaceGeneration) return;
  captureMediaSession();
  setupAutoPagination();
  connectEvents();
  scheduleEmbeddingPreparationPoll();
  scheduleSampleSuggestionPoll();
  scheduleLibrarySuggestionPoll();
  scheduleTagLibrarySuggestionPoll();
  scheduleSourceManagementPoll();
}

function expandedRefreshKinds(kinds) {
  const expanded = new Set(kinds);
  if (expanded.has("full")) {
    return new Set([
      "sourcesChanged",
      "tagsChanged",
      "assetsChanged",
      "jobsChanged",
      "reviewChanged",
    ]);
  }
  if (expanded.has("sourcesChanged") || expanded.has("tagsChanged")) {
    expanded.add("assetsChanged");
  }
  return expanded;
}

async function refreshWorkspace({ quiet = false, kinds = null } = {}) {
  const refreshGeneration = state.workspaceGeneration;
  const requestedKinds = kinds == null ? ["full"] : kinds;
  for (const kind of requestedKinds) state.pendingRefreshKinds.add(kind);
  if (
    !quiet
    || (kinds != null
      && kinds.some((kind) => ["full", "assetsChanged", "tagsChanged"].includes(kind)))
  ) {
    state.pendingInspectorRefresh = true;
  }
  if (state.refreshingWorkspace) return;

  clearTimeout(state.refreshRetryTimer);
  state.refreshRetryTimer = null;
  state.refreshingWorkspace = true;
  let failedBatch = null;
  let failedInspectorRefresh = false;
  let retryDelay = 0;
  try {
    while (state.pendingRefreshKinds.size) {
      const batch = expandedRefreshKinds(state.pendingRefreshKinds);
      state.pendingRefreshKinds.clear();
      failedBatch = batch;
      const refreshInspectorForBatch = state.pendingInspectorRefresh;
      state.pendingInspectorRefresh = false;
      failedInspectorRefresh = refreshInspectorForBatch;

      const [sources, tags, tagGroups, jobs, workspaceNotice] = await Promise.all([
        batch.has("sourcesChanged") ? api("/v1/sources") : null,
        batch.has("tagsChanged") ? api("/v1/tags") : null,
        batch.has("tagsChanged") ? api("/v1/tag-groups") : null,
        batch.has("jobsChanged") ? api("/v1/jobs") : null,
        supportsWorkspaceNotices()
          ? api("/v1/workspace-notice").catch(() => undefined)
          : null,
      ]);
      if (refreshGeneration !== state.workspaceGeneration) {
        failedBatch = null;
        return;
      }

      const sourcesChanged = Boolean(
        sources
        && projectionFingerprint(sources) !== projectionFingerprint(state.sources)
      );
      const tagsChanged = Boolean(
        tags
        && projectionFingerprint(tags) !== projectionFingerprint(state.tags)
      );
      const tagGroupsChanged = Boolean(
        tagGroups
        && projectionFingerprint(tagGroups) !== projectionFingerprint(state.tagGroups)
      );
      const jobsChanged = Boolean(
        jobs
        && projectionFingerprint(jobs) !== projectionFingerprint(state.jobs)
      );
      if (workspaceNotice !== undefined && workspaceNotice !== null
        && !state.workspaceNotice.dismissing
        && !state.workspaceNotice.activeActionID) {
        state.workspaceNotice.notice = workspaceNotice.notice || null;
        renderWorkspaceNotice();
      }
      if (sourcesChanged) {
        state.sources = sources;
        if (state.selectedSourceID
          && !state.sources.some((source) => source.id === state.selectedSourceID)) {
          state.selectedSourceID = "";
          state.selectedAssetID = null;
          state.selectedDetail = null;
        }
        renderSources();
        sanitizeReviewSourceFilter();
        renderReviewSourceFilter();
        renderReviewLocalModelStatus();
        updateLibraryTitle();
        renderLibraryEmptyState();
      }
      if (tagsChanged || tagGroupsChanged) {
        if (tags) state.tags = tags;
        if (tagGroups) state.tagGroups = tagGroups;
        const activeTagIDs = new Set(activeTags().map((tag) => tag.id));
        state.filters.tagConditions = state.filters.tagConditions.filter(
          (condition) => activeTagIDs.has(condition.tagID)
        );
        if (state.filterDraft) {
          state.filterDraft.tagConditions = state.filterDraft.tagConditions.filter(
            (condition) => activeTagIDs.has(condition.tagID)
          );
        }
        renderTagSelects();
        renderFilterChips();
      }
      if (jobsChanged) {
        state.jobs = jobs;
        renderJobs();
        if (supportsLibrarySuggestions()) {
          await loadLibrarySuggestions({ quiet: true });
        }
      }

      let assetsChanged = false;
      if (batch.has("assetsChanged")) {
        assetsChanged = await loadAssets({
          preserveSelection: true,
          preserveUnchangedGrid: true,
          preserveLoadedWindow: true,
        });
      }
      const shouldRefreshInspector = Boolean(
        state.selectedAssetID
        && (refreshInspectorForBatch || tagsChanged || assetsChanged)
        && !state.selectionMode
      );
      if (shouldRefreshInspector) {
        failedInspectorRefresh = true;
        await loadInspector(state.selectedAssetID, {
          preserveExisting: true,
          quiet: true,
          throwOnError: true,
        });
      }
      if (state.selectionMode && batch.has("tagsChanged")) {
        scheduleSelectionAggregate();
      }
      if (
        !elements.reviewWorkspace.classList.contains("hidden")
        && (batch.has("reviewChanged")
          || batch.has("assetsChanged")
          || batch.has("tagsChanged")
          || sourcesChanged)
      ) {
        await loadReviewOverview({ throwOnError: true });
        if (state.review.mode === "queue") {
          await loadReviewQueue({
            preserveUnchangedGrid: true,
            preserveLoadedWindow: true,
            throwOnError: true,
          });
        }
      }
      if (
        !elements.trainingWorkspace.classList.contains("hidden")
        && batch.has("jobsChanged")
      ) {
        await loadTrainingWorkspace({ quiet: true });
      }
      if (
        !elements.slimmingWorkspace.classList.contains("hidden")
        && batch.has("jobsChanged")
      ) {
        await loadSlimmingWorkspace({ quiet: true });
      }
      if (
        !elements.galleryOverviewWorkspace.classList.contains("hidden")
        && (batch.has("assetsChanged") || batch.has("sourcesChanged") || batch.has("tagsChanged"))
      ) {
        await loadGalleryOverview({ quiet: true, throwOnError: true });
      }
      failedBatch = null;
      failedInspectorRefresh = false;
    }
    state.refreshRetryAttempt = 0;
    if (!quiet) toast("图库已刷新");
  } catch (error) {
    if (refreshGeneration !== state.workspaceGeneration) {
      failedBatch = null;
      return;
    }
    for (const kind of failedBatch || []) state.pendingRefreshKinds.add(kind);
    if (failedInspectorRefresh) state.pendingInspectorRefresh = true;
    const retryDelays = [1000, 2000, 4000, 8000, 16000, 30000];
    retryDelay = retryDelays[
      Math.min(state.refreshRetryAttempt, retryDelays.length - 1)
    ];
    state.refreshRetryAttempt += 1;
    if (!quiet) toast(error.message || "刷新失败");
  } finally {
    state.refreshingWorkspace = false;
    if (state.pendingRefreshKinds.size) {
      state.refreshRetryTimer = setTimeout(
        () => refreshWorkspace({ quiet: true, kinds: [] }),
        retryDelay
      );
    }
  }
}

function socketURL() {
  const scheme = location.protocol === "https:" ? "wss:" : "ws:";
  return `${scheme}//${location.host}/v1/events/websocket`;
}

function disconnectEvents() {
  state.socketGeneration += 1;
  clearTimeout(state.accountPollTimer);
  state.accountPollTimer = null;
  if (state.socket) {
    state.socket.onclose = null;
    state.socket.close();
    state.socket = null;
  }
}

function scheduleProjectionPoll(generation) {
  clearTimeout(state.accountPollTimer);
  const interval = state.authMode === "account" ? 10_000 : 15_000;
  state.accountPollTimer = setTimeout(async () => {
    if (generation !== state.socketGeneration
      || !["account", "pairedDevice"].includes(state.authMode)
      || elements.appView.classList.contains("hidden")) return;
    try {
      await api("/web/session", {}, false);
      await refreshWorkspace({ quiet: true });
      setConnection(true, state.authMode === "account" ? "账号已登录" : "已连接");
      scheduleProjectionPoll(generation);
    } catch (error) {
      if (error.status === 401) {
        if (state.authMode === "account") {
          state.accountAuthorization = null;
          state.authMode = null;
          showPairing("账号密码无效或已从 Mac 白名单移除。");
        } else {
          showPairing("网页会话已过期，请在 Mac 上重新配对。");
        }
      } else {
        setConnection(false);
        scheduleProjectionPoll(generation);
      }
    }
  }, interval);
}

function scheduleEventReconnect(generation) {
  const delays = [1000, 2000, 4000, 8000, 16000, 30000];
  const delay = delays[Math.min(state.reconnectAttempt, delays.length - 1)];
  state.reconnectAttempt += 1;
  setTimeout(() => {
    if (generation === state.socketGeneration && !elements.appView.classList.contains("hidden")) {
      connectEvents();
    }
  }, delay);
}

async function connectEvents() {
  disconnectEvents();
  const generation = state.socketGeneration;
  if (state.authMode === "account") {
    try {
      await api("/web/session", {}, false);
      if (generation !== state.socketGeneration) return;
      state.reconnectAttempt = 0;
      setConnection(true, "账号已登录");
      scheduleProjectionPoll(generation);
    } catch (error) {
      if (error.status === 401) {
        state.accountAuthorization = null;
        state.authMode = null;
        showPairing("账号密码无效或已从 Mac 白名单移除。");
      } else {
        setConnection(false);
        scheduleProjectionPoll(generation);
      }
    }
    return;
  }
  setConnection(true, "正在连接实时更新");
  try {
    await api("/web/session");
  } catch (error) {
    if (generation !== state.socketGeneration) return;
    if (error.status === 401) {
      showPairing("网页会话已过期，请在 Mac 上重新配对。");
      return;
    }
    setConnection(false);
    scheduleEventReconnect(generation);
    return;
  }
  if (generation !== state.socketGeneration) return;
  scheduleProjectionPoll(generation);

  const socket = new WebSocket(socketURL());
  state.socket = socket;
  socket.addEventListener("open", () => {
    if (generation !== state.socketGeneration) return;
    state.reconnectAttempt = 0;
    setConnection(true);
  });
  socket.addEventListener("message", (event) => {
    if (generation !== state.socketGeneration) return;
    try {
      const message = JSON.parse(event.data);
      if (message.kind === "ping") return;
      state.pendingRefreshKinds.add(message.kind);
      if (["full", "assetsChanged", "tagsChanged"].includes(message.kind)) {
        state.pendingInspectorRefresh = true;
      }
      clearTimeout(state.eventRefreshTimer);
      state.eventRefreshTimer = setTimeout(
        () => refreshWorkspace({ quiet: true, kinds: [] }),
        280
      );
    } catch {
      // Ignore malformed events while preserving the live connection.
    }
  });
  socket.addEventListener("close", () => {
    if (generation !== state.socketGeneration) return;
    state.socket = null;
    setConnection(false);
    scheduleEventReconnect(generation);
  });
  socket.addEventListener("error", () => {
    if (generation === state.socketGeneration) setConnection(false);
  });
}

async function pair(event) {
  event.preventDefault();
  const pairingToken = elements.pairingToken.value.trim();
  const deviceName = elements.deviceName.value.trim();
  if (!pairingToken || !deviceName) return;

  elements.pairButton.disabled = true;
  elements.pairButton.textContent = "正在连接…";
  elements.pairingError.textContent = "";
  try {
    state.accountAuthorization = null;
    await updateMediaWorkerAuthorization(null);
    await api("/web/session/pair", {
      method: "POST",
      body: JSON.stringify({
        pairingToken,
        deviceName,
        clientID: clientID(),
      }),
    }, false);
    state.authMode = "pairedDevice";
    elements.pairingToken.value = "";
    await loadWorkspace();
  } catch (error) {
    const message = /invalidToken|noActiveOffer|offerExpired/.test(error.message)
      ? "配对码无效或已过期，请在 Mac 上重新开始配对。"
      : (error.message || "无法完成配对");
    elements.pairingError.textContent = message;
  } finally {
    elements.pairButton.disabled = false;
    elements.pairButton.textContent = "连接图库";
  }
}

async function loginWithAccount(event) {
  event.preventDefault();
  const username = elements.accountUsername.value.trim();
  const password = elements.accountPassword.value;
  if (!username || !password) return;

  elements.accountLoginButton.disabled = true;
  elements.accountLoginButton.textContent = "正在登录…";
  elements.accountLoginError.textContent = "";
  const authorization = basicAuthorization(username, password);
  state.accountAuthorization = authorization;
  try {
    const session = await api("/web/account/login", {
      method: "POST",
      body: "{}",
    }, false);
    state.authMode = session.authMode || "account";
    await updateMediaWorkerAuthorization(state.accountAuthorization);
    elements.accountPassword.value = "";
    await loadWorkspace();
  } catch (error) {
    state.accountAuthorization = null;
    state.authMode = null;
    updateMediaWorkerAuthorization(null);
    elements.accountLoginError.textContent = error.status === 401
      ? "账号名或密码不正确，或该账号不在 Mac 白名单中。"
      : (error.message || "无法登录图库");
  } finally {
    elements.accountLoginButton.disabled = false;
    elements.accountLoginButton.textContent = "登录图库";
  }
}

